/* DAWAH X — ahmad, অধ্যায় 84 · খণ্ড 84 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][84]=[[16601,16601,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ مُزَيْنَةَ ‏ ‏أَنَّهُ ‏ ‏قَالَتْ لَهُ أُمُّهُ أَلَا تَنْطَلِقُ فَتَسْأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا يَسْأَلُهُ النَّاسُ فَانْطَلَقْتُ أَسْأَلُهُ فَوَجَدْتُهُ قَائِمًا يَخْطُبُ وَهُوَ يَقُولُ ‏ ‏مَنْ ‏ ‏اسْتَعَفَّ ‏ ‏أَعَفَّهُ ‏ ‏اللَّهُ وَمَنْ اسْتَغْنَى أَغْنَاهُ اللَّهُ وَمَنْ سَأَلَ النَّاسَ وَلَهُ ‏ ‏عِدْلُ ‏ ‏خَمْسِ ‏ ‏أَوَاقٍ ‏ ‏فَقَدْ سَأَلَ ‏ ‏إِلْحَافًا ‏ ‏فَقُلْتُ بَيْنِي وَبَيْنَ نَفْسِي لَنَاقَةٌ لَهُ هِيَ خَيْرٌ مِنْ خَمْسِ ‏ ‏أَوَاقٍ ‏ ‏وَلِغُلَامِهِ نَاقَةٌ أُخْرَى هِيَ خَيْرٌ مِنْ خَمْسِ ‏ ‏أَوَاقٍ ‏ ‏فَرَجَعْتُ وَلَمْ أَسْأَلْهُ ‏","","",""],[16602,16602,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَمْعَةُ بْنُ صَالِحٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ شِهَابٍ ‏ ‏يُحَدِّثُ أَنَّ ‏ ‏أَبَا أُمَامَةَ بْنَ سَهْلِ بْنِ حُنَيْفٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي أُمَامَةَ أَسْعَدَ بْنِ زُرَارَةَ ‏ ‏وَكَانَ أَحَدَ ‏ ‏النُّقَبَاءِ ‏ ‏يَوْمَ ‏ ‏الْعَقَبَةِ ‏ ‏أَنَّهُ أَخَذَتْهُ الشَّوْكَةُ فَجَاءَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعُودُهُ فَقَالَ ‏ ‏بِئْسَ الْمَيِّتُ ‏ ‏لَيَهُودُ ‏ ‏مَرَّتَيْنِ سَيَقُولُونَ لَوْلَا دَفَعَ عَنْ صَاحِبِهِ وَلَا أَمْلِكُ لَهُ ضَرًّا وَلَا نَفْعًا وَلَأَتَمَحَّلَنَّ لَهُ فَأَمَرَ بِهِ وَكُوِيَ بِخَطَّيْنِ فَوْقَ رَأْسِهِ فَمَاتَ ‏","","",""],[16603,16603,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِئُ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو عَمْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ أَرْبَعَةُ نَفَرٍ وَمَعَنَا فَرَسٌ ‏ ‏فَأَعْطَى كُلَّ إِنْسَانٍ مِنَّا سَهْمًا وَأَعْطَى الْفَرَسَ سَهْمَيْنِ ‏","","",""],[16604,16604,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَارَةَ بْنَ خُزَيْمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُثْمَانَ بْنِ حُنَيْفٍ ‏ ‏أَنَّ رَجُلًا ضَرِيرَ الْبَصَرِ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ادْعُ اللَّهَ أَنْ يُعَافِيَنِي قَالَ إِنْ شِئْتَ دَعَوْتُ لَكَ وَإِنْ شِئْتَ أَخَّرْتُ ذَاكَ فَهُوَ خَيْرٌ فَقَالَ ادْعُهُ فَأَمَرَهُ أَنْ يَتَوَضَّأَ فَيُحْسِنَ وُضُوءَهُ فَيُصَلِّيَ رَكْعَتَيْنِ وَيَدْعُوَ بِهَذَا الدُّعَاءِ ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ وَأَتَوَجَّهُ إِلَيْكَ بِنَبِيِّكَ ‏ ‏مُحَمَّدٍ ‏ ‏نَبِيِّ الرَّحْمَةِ ‏ ‏يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنِّي تَوَجَّهْتُ بِكَ إِلَى رَبِّي فِي حَاجَتِي هَذِهِ ‏ ‏فَتَقْضِي لِي ‏ ‏اللَّهُمَّ شَفِّعْهُ فِيَّ ‏","","",""],[16605,16605,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ الْمَدِينِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَارَةَ بْنَ خُزَيْمَةَ بْنِ ثَابِتٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُثْمَانَ بْنِ حُنَيْفٍ ‏ ‏أَنَّ رَجُلًا ضَرِيرًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا نَبِيَّ اللَّهِ ادْعُ اللَّهَ أَنْ يُعَافِيَنِي فَقَالَ إِنْ شِئْتَ أَخَّرْتُ ذَلِكَ فَهُوَ أَفْضَلُ لِآخِرَتِكَ وَإِنْ شِئْتَ دَعَوْتُ لَكَ قَالَ لَا بَلْ ادْعُ اللَّهَ لِي ‏ ‏فَأَمَرَهُ أَنْ يَتَوَضَّأَ وَأَنْ يُصَلِّيَ رَكْعَتَيْنِ وَأَنْ يَدْعُوَ بِهَذَا الدُّعَاءِ اللَّهُمَّ إِنِّي أَسْأَلُكَ وَأَتَوَجَّهُ إِلَيْكَ بِنَبِيِّكَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَبِيِّ الرَّحْمَةِ ‏ ‏يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنِّي أَتَوَجَّهُ بِكَ إِلَى رَبِّي فِي حَاجَتِي هَذِهِ ‏ ‏فَتَقْضِي وَتُشَفِّعُنِي فِيهِ وَتُشَفِّعُهُ فِيَّ قَالَ فَكَانَ يَقُولُ هَذَا مِرَارًا ثُمَّ قَالَ بَعْدُ أَحْسِبُ أَنَّ فِيهَا أَنْ تُشَفِّعَنِي فِيهِ قَالَ فَفَعَلَ الرَّجُلُ فَبَرَأَ ‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ الْخَطْمِيُّ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ خُزَيْمَةَ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ حُنَيْفٍ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ذَهَبَ بَصَرُهُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[16606,16606,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَارِثُ بْنُ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عُثْمَانَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏هَانِئِ بْنِ مُعَاوِيَةَ الصَّدَفِيِّ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏حَجَجْتُ زَمَانَ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏فَجَلَسْتُ فِي ‏ ‏مَسْجِدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا رَجُلٌ يُحَدِّثُهُمْ قَالَ كُنَّا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا فَأَقْبَلَ رَجُلٌ فَصَلَّى فِي هَذَا ‏ ‏الْعَمُودِ فَعَجَّلَ قَبْلَ أَنْ يُتِمَّ صَلَاتَهُ ثُمَّ خَرَجَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذَا لَوْ مَاتَ لَمَاتَ وَلَيْسَ مِنْ الدِّينِ عَلَى شَيْءٍ إِنَّ الرَّجُلَ لَيُخَفِّفُ صَلَاتَهُ وَيُتِمُّهَا قَالَ فَسَأَلْتُ عَنْ الرَّجُلِ مَنْ هُوَ فَقِيلَ ‏ ‏عُثْمَانُ بْنُ حُنَيْفٍ الْأَنْصَارِيُّ ‏","","",""],[16607,16607,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيُّ ‏ ‏وَعَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ عَمْرِو بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى الْخُفَّيْنِ ‏","","",""],[16608,16608,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى الْخُفَّيْنِ ‏ ‏وَالْخِمَارِ ‏","","",""],[16609,16609,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏وَحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏أَنَّ ‏ ‏جَعْفَرَ بْنَ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى الْخُفَّيْنِ ‏","","",""],[16610,16610,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ يَعْنِي ابْنَ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جَعْفَرُ بْنُ عَمْرِو بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى الْخُفَّيْنِ ‏","","",""],[16611,16611,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ عَمْرِو بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ عُضْوًا ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[16612,16612,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ عَمْرِو بْنِ أُمَيَّةَ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْتَزُّ ‏ ‏مِنْ كَتِفِ شَاةٍ فَدُعِيَ إِلَى الصَّلَاةِ فَطَرَحَ السِّكِّينَ وَلَمْ يَتَوَضَّأْ ‏","","",""],[16613,16613,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ عَمْرِو بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُ ‏ ‏يَحْتَزُّ ‏ ‏مِنْ كَتِفِ شَاةٍ ثُمَّ دُعِيَ إِلَى الصَّلَاةِ فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[16614,16614,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَيَّاشُ بْنُ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏كُلَيْبَ بْنَ صُبَيْحٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏الزِّبْرِقَانَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عَمِّهِ ‏ ‏عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ أَسْفَارِهِ فَنَامَ عَنْ صَلَاةِ الصُّبْحِ حَتَّى طَلَعَتْ الشَّمْسُ لَمْ يَسْتَيْقِظُوا وَأَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَدَأَ بِالرَّكْعَتَيْنِ فَرَكَعَهُمَا ثُمَّ أَقَامَ الصَّلَاةَ فَصَلَّى ‏","","",""],[16615,16615,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي شَيْبَةَ ‏ ‏بِالْكُوفَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ إِسْمَاعِيلَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جَعْفَرُ بْنُ عَمْرِو بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَهُ وَحْدَهُ ‏ ‏عَيْنًا ‏ ‏إِلَى ‏ ‏قُرَيْشٍ ‏ ‏قَالَ جِئْتُ إِلَى خَشَبَةِ ‏ ‏خُبَيْبٍ ‏ ‏وَأَنَا أَتَخَوَّفُ الْعُيُونَ فَرَقِيتُ فِيهَا فَحَلَلْتُ ‏ ‏خُبَيْبًا ‏ ‏فَوَقَعَ إِلَى الْأَرْضِ ‏ ‏فَانْتَبَذْتُ ‏ ‏غَيْرَ بَعِيدٍ ثُمَّ الْتَفَتُّ فَلَمْ أَرَ ‏ ‏خُبَيْبًا ‏ ‏وَلَكَأَنَّمَا ابْتَلَعَتْهُ الْأَرْضُ فَلَمْ يُرَ ‏ ‏لِخُبَيْبٍ ‏ ‏أَثَرٌ حَتَّى السَّاعَةِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَقَالَ ‏ ‏ابْنُ أَبِي شَيْبَةَ ‏ ‏لَنَا فِيهِ عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏وَأَمَّا أَبِي فَحَدَّثَنَا عَنْهُ لَمْ يَذْكُرْ ‏ ‏الزُّهْرِيَّ ‏ ‏وَحَدَّثَنَاهُ ‏ ‏ابْنُ أَبِي شَيْبَةَ ‏ ‏بِالْكُوفَةِ ‏ ‏فَجَعَلَهُ لَنَا ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏","","",""],[16616,16616,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو كَثِيرٍ ‏ ‏مَوْلَى ‏ ‏اللَّيْثِيِّينَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ جَحْشٍ ‏ ‏أَنَّ رَجُلًا جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مَاذَا لِي ‏ ‏إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ قَالَ الْجَنَّةُ فَلَمَّا ‏ ‏وَلَّى ‏ ‏قَالَ إِلَّا الدَّيْنُ ‏ ‏سَارَّنِي ‏ ‏بِهِ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏آنِفًا ‏","","",""],[16617,16617,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي كَثِيرٍ ‏ ‏مَوْلَى ‏ ‏الْهِلَالِيِّينَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ جَحْشٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مَاذَا لِي ‏ ‏إِنْ قَاتَلْتُ فِي سَبِيلِ اللَّهِ حَتَّى أُقْتَلَ قَالَ الْجَنَّةُ قَالَ فَلَمَّا ‏ ‏وَلَّى ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا الدَّيْنُ ‏ ‏سَارَّنِي ‏ ‏بِهِ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏آنِفًا ‏","","",""],[16618,16618,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ يَعْنِي ابْنَ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي مَالِكٍ الْأَشْجَعِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَعْظَمُ ‏ ‏الْغُلُولِ ‏ ‏عِنْدَ اللَّهِ عَزَّ وَجَلَّ ذِرَاعٌ مِنْ الْأَرْضِ تَجِدُونَ الرَّجُلَيْنِ جَارَيْنِ فِي الْأَرْضِ أَوْ فِي الدَّارِ فَيَقْتَطِعُ أَحَدُهُمَا مِنْ حَظِّ صَاحِبِهِ ذِرَاعًا فَإِذَا اقْتَطَعَهُ ‏ ‏طُوِّقَهُ ‏ ‏مِنْ سَبْعِ أَرَضِينَ إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[16619,16619,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏بَلَغَهُ أَنَّ ‏ ‏رَافِعًا ‏ ‏يُحَدِّثُ فِي ذَلِكَ بِنَهْيٍ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَاهُ وَأَنَا مَعَهُ فَسَأَلَهُ فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏كِرَاءِ ‏ ‏الْمَزَارِعِ فَتَرَكَهَا ‏ ‏ابْنُ عُمَرَ ‏ ‏فَكَانَ لَا ‏ ‏يُكْرِيهَا ‏ ‏فَكَانَ إِذَا سُئِلَ يَقُولُ زَعَمَ ‏ ‏ابْنُ خَدِيجٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏كِرَاءِ ‏ ‏الْمَزَارِعِ ‏","","",""],[16620,16620,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَصْبِحُوا بِالصُّبْحِ فَإِنَّهُ أَعْظَمُ لِأُجُورِكُمْ ‏ ‏أَوْ أَعْظَمُ لِلْأَجْرِ ‏","","",""],[16621,16621,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَبِيعَةُ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏كِرَاءِ ‏ ‏الْمَزَارِعِ قَالَ قُلْتُ بِالذَّهَبِ وَالْفِضَّةِ قَالَ لَا إِنَّمَا نَهَى عَنْهُ بِبَعْضِ مَا يَخْرُجُ مِنْهَا فَأَمَّا بِالذَّهَبِ وَالْفِضَّةِ فَلَا بَأْسَ بِهِ ‏","","",""],[16622,16622,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏السَّائِبَ بْنَ يَزِيدَ بْنِ أُخْتِ النِّمْرِ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏شَرُّ الْكَسْبِ ثَمَنُ الْكَلْبِ ‏ ‏وَكَسْبُ الْحَجَّامِ ‏ ‏وَمَهْرُ الْبَغِيِّ ‏","","",""],[16623,16623,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا قَطْعَ فِي ثَمَرٍ وَلَا ‏ ‏كَثَرٍ ‏","","",""],[16624,16624,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَبَايَةَ بْنِ رِفَاعَةَ بْنِ رَافِعِ بْنِ خَدِيجٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّا لَاقُو الْعَدُوِّ غَدًا وَلَيْسَتْ مَعَنَا مُدًى قَالَ أَعْجِلْ أَوْ أَرِنْ مَا أَنْهَرَ الدَّمَ وَذُكِرَ اسْمُ اللَّهِ عَلَيْهِ فَكُلْ لَيْسَ السِّنَّ وَالظُّفُرَ وَسَأُحَدِّثُكَ أَمَّا السِّنُّ فَعَظْمٌ وَأَمَّا الظُّفُرُ فَمُدَى ‏ ‏الْحَبَشَةِ ‏ ‏قَالَ وَأَصَابَنَا نَهْبُ إِبِلٍ وَغَنَمٍ فَنَدَّ مِنْهَا بَعِيرٌ فَرَمَاهَا رَجُلٌ بِسَهْمٍ فَحَبَسَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لَهَذِهِ الْإِبِلِ ‏ ‏أَوَابِدَ ‏ ‏كَأَوَابِدِ ‏ ‏الْوَحْشِ فَإِذَا غَلَبَكُمْ مِنْهَا شَيْءٌ فَافْعَلُوا بِهِ هَكَذَا ‏","","",""],[16625,16625,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ كَثِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بُشَيْرُ بْنُ يَسَارٍ ‏ ‏مَوْلَى ‏ ‏بَنِي حَارِثَةَ ‏ ‏أَنَّ ‏ ‏رَافِعَ بْنَ خَدِيجٍ ‏ ‏وَسَهْلَ بْنَ أَبِي حَثْمَةَ ‏ ‏حَدَّثَاهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمُزَابَنَةِ ‏ ‏الثَّمَرِ ‏ ‏بِالتَّمْرِ إِلَّا أَصْحَابَ ‏ ‏الْعَرَايَا ‏ ‏فَإِنَّهُ قَدْ أَذِنَ لَهُمْ ‏","","",""],[16626,16626,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبَايَةَ بْنِ رِفَاعَةَ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏مِنْ ‏ ‏تِهَامَةَ ‏ ‏فَأَصَبْنَا غَنَمًا وَإِبِلًا قَالَ فَعَجَّلَ الْقَوْمُ فَأَغْلَوْا بِهَا الْقُدُورَ فَجَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَ بِهَا فَأُكْفِئَتْ ثُمَّ قَالَ عَدْلُ عَشْرَةٍ مِنْ الْغَنَمِ ‏ ‏بِجَزُورٍ ‏ ‏قَالَ ثُمَّ إِنَّ بَعِيرًا ‏ ‏نَدَّ ‏ ‏وَلَيْسَ فِي الْقَوْمِ إِلَّا خَيْلٌ يَسِيرَةٌ فَرَمَاهُ رَجُلٌ بِسَهْمٍ فَحَبَسَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِهَذِهِ الْبَهَائِمِ ‏ ‏أَوَابِدَ ‏ ‏كَأَوَابِدِ ‏ ‏الْوَحْشِ فَمَا غَلَبَكُمْ مِنْهَا فَاصْنَعُوا بِهِ هَكَذَا قَالَ فَقَالَ ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏إِنَّا لَنَرْجُو وَإِنَّا لَنَخَافُ أَنْ نَلْقَى الْعَدُوَّ غَدًا وَلَيْسَ مَعَنَا ‏ ‏مُدًى ‏ ‏أَفَنَذْبَحُ ‏ ‏بِالْقَصَبِ ‏ ‏قَالَ أَعْجِلْ أَوْ أَرِنْ مَا ‏ ‏أَنْهَرَ ‏ ‏الدَّمَ وَذُكِرَ اسْمُ اللَّهِ عَلَيْهِ فَكُلْ لَيْسَ السِّنَّ ‏ ‏وَالظُّفُرَ وَسَأُحَدِّثُكُمْ عَنْ ذَلِكَ أَمَّا السِّنُّ فَعَظْمٌ وَأَمَّا الظُّفُرُ ‏ ‏فَمُدَى ‏ ‏الْحَبَشَةِ ‏","","",""],[16627,16627,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تُسْتَأْجَرَ الْأَرْضُ بِالدَّرَاهِمِ الْمَنْقُودَةِ أَوْ بِالثُّلُثِ وَالرُّبُعِ ‏","","",""],[16628,16628,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏وَائِلٍ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَبَايَةَ بْنِ رِفَاعَةَ بْنِ رَافِعِ بْنِ خَدِيجٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ أَيُّ الْكَسْبِ أَطْيَبُ قَالَ ‏ ‏عَمَلُ الرَّجُلِ بِيَدِهِ وَكُلُّ بَيْعٍ ‏ ‏مَبْرُورٍ ‏","","",""],[16629,16629,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبَايَةَ بْنِ رِفَاعَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْحُمَّى ‏ ‏مِنْ فَوْرِ جَهَنَّمَ فَأَبْرِدُوهَا بِالْمَاءِ ‏","","",""],[16630,16630,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ ‏ ‏عَنْ ‏ ‏أَبِي النَّجَاشِيِّ ‏ ‏مَوْلَى ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏رَافِعًا ‏ ‏عَنْ ‏ ‏كِرَاءِ ‏ ‏الْأَرْضِ قُلْتُ إِنَّ لِي أَرْضًا ‏ ‏أُكْرِيهَا ‏ ‏فَقَالَ ‏ ‏رَافِعٌ ‏ ‏لَا ‏ ‏تُكْرِهَا ‏ ‏بِشَيْءٍ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَتْ لَهُ أَرْضٌ فَلْيَزْرَعْهَا فَإِنْ لَمْ يَزْرَعْهَا فَلْيُزْرِعْهَا أَخَاهُ فَإِنْ لَمْ يَفْعَلْ فَلْيَدَعْهَا فَقُلْتُ لَهُ أَرَأَيْتَ إِنْ تَرَكْتُهُ وَأَرْضِي فَإِنْ زَرَعَهَا ثُمَّ بَعَثَ إِلَيَّ مِنْ التِّبْنِ قَالَ لَا تَأْخُذْ مِنْهَا شَيْئًا وَلَا تِبْنًا قُلْتُ إِنِّي لَمْ ‏ ‏أُشَارِطْهُ ‏ ‏إِنَّمَا أَهْدَى إِلَيَّ شَيْئًا قَالَ لَا تَأْخُذْ مِنْهُ شَيْئًا ‏","","",""],[16631,16631,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي سُلَيْمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبَايَةَ بْنَ رِفَاعَةَ بْنِ رَافِعِ بْنِ خَدِيجٍ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ ‏ ‏جَدَّهُ ‏ ‏حِينَ مَاتَ تَرَكَ ‏ ‏جَارِيَةً ‏ ‏وَنَاضِحًا ‏ ‏وَغُلَامًا ‏ ‏حَجَّامًا ‏ ‏وَأَرْضًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْجَارِيَةِ ‏ ‏فَنَهَى عَنْ كَسْبِهَا قَالَ ‏ ‏شُعْبَةُ ‏ ‏مَخَافَةَ أَنْ ‏ ‏تَبْغِيَ ‏ ‏وَقَالَ مَا أَصَابَ ‏ ‏الْحَجَّامُ ‏ ‏فَاعْلِفْهُ ‏ ‏النَّاضِحَ ‏ ‏وَقَالَ فِي الْأَرْضِ ازْرَعْهَا أَوْ ‏ ‏ذَرْهَا ‏","","",""],[16632,16632,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏وَالْخُزَاعِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ زَرَعَ فِي أَرْضِ قَوْمٍ بِغَيْرِ إِذْنِهِمْ فَلَيْسَ لَهُ مِنْ الزَّرْعِ شَيْءٌ وَتُرَدُّ عَلَيْهِ نَفَقَتُهُ ‏ ‏قَالَ ‏ ‏الْخُزَاعِيُّ ‏ ‏مَا أَنْفَقَهُ وَلَيْسَ لَهُ مِنْ الزَّرْعِ شَيْءٌ ‏","","",""],[16633,16633,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ قَارِظٍ ‏ ‏عَنْ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَمَنُ الْكَلْبِ خَبِيثٌ وَمَهْرُ الْبَغِيِّ خَبِيثٌ وَكَسْبُ ‏ ‏الْحَجَّامِ ‏ ‏خَبِيثٌ ‏","","",""],[16634,16634,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ذَكَرَ ‏ ‏مَكَّةَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏إِبْرَاهِيمَ ‏ ‏حَرَّمَ ‏ ‏مَكَّةَ ‏ ‏وَإِنِّي أُحَرِّمُ مَا بَيْنَ لَابَتَيْهَا ‏","","",""],[16635,16635,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏عُتْبَةَ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏قَالَ خَطَبَ ‏ ‏مَرْوَانُ ‏ ‏النَّاسَ فَذَكَرَ ‏ ‏مَكَّةَ ‏ ‏وَحُرْمَتَهَا فَنَادَاهُ ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏فَقَالَ إِنَّ ‏ ‏مَكَّةَ ‏ ‏إِنْ تَكُنْ حَرَمًا ‏ ‏فَإِنَّ ‏ ‏الْمَدِينَةَ ‏ ‏حَرَمٌ حَرَّمَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مَكْتُوبٌ عِنْدَنَا فِي ‏ ‏أَدِيمٍ ‏ ‏خَوْلَانِيٍّ إِنْ شِئْتَ أَنْ نُقْرِئَكَهُ فَعَلْنَا فَنَادَاهُ ‏ ‏مَرْوَانُ ‏ ‏أَجَلْ قَدْ بَلَغَنَا ذَلِكَ ‏","","",""],[16636,16636,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏حَرَّمَ ‏ ‏مَكَّةَ ‏ ‏وَإِنِّي أُحَرِّمُ مَا بَيْنَ لَابَتَيْهَا يُرِيدُ ‏ ‏الْمَدِينَةَ ‏","","",""],[16637,16637,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏الْحُمْرَةَ ‏ ‏قَدْ ظَهَرَتْ فَكَرِهَهَا ‏ ‏فَلَمَّا مَاتَ ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏جَعَلُوا عَلَى سَرِيرِهِ قَطِيفَةً حَمْرَاءَ فَعَجِبَ النَّاسُ مِنْ ذَلِكَ ‏","","",""],[16638,16638,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو النَّجَاشِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْعَصْرِ ثُمَّ ‏ ‏نَنْحَرُ ‏ ‏الْجَزُورَ ‏ ‏فَتُقْسَمُ عَشَرَ قَسْمٍ ثُمَّ تُطْبَخُ فَنَأْكُلُ لَحْمًا نَضِيجًا قَبْلَ أَنْ تَغِيبَ الشَّمْسُ قَالَ وَكُنَّا نُصَلِّي الْمَغْرِبَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَنْصَرِفُ أَحَدُنَا وَإِنَّهُ لَيَنْظُرُ إِلَى مَوَاقِعِ نَبْلِهِ ‏","","",""],[16639,16639,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ أَبِي حَثْمَةَ ‏ ‏وَرَافِعِ بْنِ خَدِيجٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ سَهْلٍ ‏ ‏وَمُحَيِّصَةَ بْنَ مَسْعُودٍ ‏ ‏أَتَيَا ‏ ‏خَيْبَرَ ‏ ‏فِي حَاجَةٍ لَهُمَا فَتَفَرَّقَا فَقُتِلَ ‏ ‏عَبْدُ اللَّهِ بْنُ سَهْلٍ ‏ ‏وَوَجَدُوهُ قَتِيلًا قَالَ فَجَاءَ ‏ ‏مُحَيِّصَةُ ‏ ‏وَحُوَيِّصَةُ ‏ ‏ابْنَا ‏ ‏مَسْعُودٍ ‏ ‏وَجَاءَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ سَهْلٍ ‏ ‏أَخُو الْقَتِيلِ وَكَانَ أَحْدَثَهُمَا فَأَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَكَلَّمَ فَبَدَأَ الَّذِي أَوْلَى بِالدَّمِ وَكَانَا هَذَيْنِ ‏ ‏أَسَنُّ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَبِّرْ الْكِبَرَ قَالَ فَتَكَلَّمَا فِي أَمْرِ صَاحِبِهِمَا قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَحِقُّوا ‏ ‏صَاحِبَكُمْ ‏ ‏أَوْ قَتِيلَكُمْ ‏ ‏بِأَيْمَانِ خَمْسِينَ مِنْكُمْ قَالُوا يَا رَسُولَ اللَّهِ أَمْرٌ لَمْ نَشْهَدْ فَكَيْفَ نَحْلِفُ قَالَ فَتُبْرِئُكُمْ ‏ ‏يَهُودُ ‏ ‏بِخَمْسِينَ أَيْمَانًا مِنْهُمْ فَقَالُوا قَوْمٌ كُفَّارٌ قَالَ ‏ ‏فَوَدَاهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ قِبَلِهِ ‏ ‏قَالَ ‏ ‏فَدَخَلْتُ ‏ ‏مِرْبَدًا ‏ ‏لَهُمْ ‏ ‏فَرَكَضَتْنِي ‏ ‏نَاقَةٌ مِنْ تِلْكَ الْإِبِلِ الَّتِي وَدَاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرِجْلِهَا ‏ ‏رَكْضَةً ‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ أَبِي حَثْمَةَ ‏ ‏وَرَافِعِ بْنِ خَدِيجٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[16640,16640,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏أَنَّهُ قَالَ حَدَّثَنِي ‏ ‏عَمِّي ‏ ‏أَنَّهُمْ كَانُوا ‏ ‏يُكْرُونَ ‏ ‏الْأَرْضَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَا يُنْبِتُ عَلَى ‏ ‏الْأَرْبِعَاءِ ‏ ‏وَشَيْئًا مِنْ الزَّرْعِ يَسْتَثْنِيهِ صَاحِبُ الزَّرْعِ ‏ ‏فَنَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ ‏ ‏فَقُلْتُ ‏ ‏لِرَافِعٍ ‏ ‏كَيْفَ ‏ ‏كِرَاؤُهَا ‏ ‏بِالدِّينَارِ وَالدِّرْهَمِ فَقَالَ ‏ ‏رَافِعٌ ‏ ‏لَيْسَ بِهَا بَأْسٌ بِالدِّينَارِ وَالدِّرْهَمِ ‏","","",""],[16641,16641,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْفِرُوا ‏ ‏بِالْفَجْرِ فَإِنَّهُ أَعْظَمُ لِلْأَجْرِ ‏ ‏أَوْ لِأَجْرِهَا ‏","","",""],[16642,16642,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرًا ‏ ‏قَالَ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُخَابِرُ ‏ ‏وَلَا نَرَى بِذَلِكَ بَأْسًا حَتَّى زَعَمَ ‏ ‏رَافِعٌ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْهُ فَتَرَكْنَاهُ ‏","","",""],[16643,16643,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَىِ بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا قَطْعَ فِي ثَمَرٍ وَلَا ‏ ‏كَثَرٍ ‏","","",""],[16644,16644,"","","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مَخْلَدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْوَاحِدِ بْنِ نَافِعٍ الْكَلَاعِيِّ ‏ ‏مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏قَالَ مَرَرْتُ بِمَسْجِدٍ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَأُقِيمَتْ الصَّلَاةُ فَإِذَا شَيْخٌ فَلَامَ الْمُؤَذِّنَ وَقَالَ أَمَا عَلِمْتَ أَنَّ ‏ ‏أَبِي ‏ ‏أَخْبَرَنِي ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَأْمُرُ بِتَأْخِيرِ هَذِهِ الصَّلَاةِ قَالَ قُلْتُ مَنْ هَذَا الشَّيْخُ قَالُوا هَذَا ‏ ‏عَبْدُ اللَّهِ بْنُ رَافِعِ بْنِ خَدِيجٍ ‏","","",""],[16645,16645,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبَايَةَ بْنِ رِفَاعَةَ بْنِ رَافِعِ بْنِ خَدِيجٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّا لَاقُو الْعَدُوِّ غَدًا وَلَيْسَ مَعَنَا ‏ ‏مُدًى ‏ ‏قَالَ مَا أَنْهَرَ الدَّمَ وَذُكِرَ اسْمُ اللَّهِ عَلَيْهِ فَكُلْ لَيْسَ السِّنَّ وَالظُّفُرَ وَسَأُحَدِّثُكَ أَمَّا السِّنُّ فَعَظْمٌ وَأَمَّا الظُّفُرُ ‏ ‏فَمُدَى ‏ ‏الْحَبَشَةِ ‏ ‏قَالَ وَأَصَابَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهْبًا ‏ ‏فَنَدَّ ‏ ‏مِنْهَا بَعِيرٌ فَسَعَوْا لَهُ فَلَمْ يَسْتَطِيعُوهُ فَرَمَاهُ رَجُلٌ بِسَهْمٍ فَحَبَسَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِهَذِهِ الْإِبِلِ ‏ ‏أَوْ قَالَ النَّعَمِ ‏ ‏أَوَابِدَ ‏ ‏كَأَوَابِدِ ‏ ‏الْوَحْشِ فَمَا غَلَبَكُمْ فَاصْنَعُوا بِهِ هَكَذَا ‏","","",""],[16646,16646,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏أَنَّ النَّاسَ كَانُوا ‏ ‏يُكْرُونَ ‏ ‏الْمَزَارِعَ فِي زَمَانِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَاذِيَانَاتِ ‏ ‏وَمَا سَقَى الرَّبِيعُ وَشَيْءٍ مِنْ ‏ ‏التِّبْنِ ‏ ‏فَكَرِهَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كِرَاءَ ‏ ‏الْمَزَارِعِ بِهَذَا وَنَهَى عَنْهَا ‏ ‏قَالَ ‏ ‏رَافِعٌ ‏ ‏وَلَا بَأْسَ ‏ ‏بِكِرَائِهَا ‏ ‏بِالدَّرَاهِمِ وَالدَّنَانِيرِ ‏","","",""],[16647,16647,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَاصِمُ بْنُ عُمَرَ بْنِ قَتَادَةَ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْعَامِلُ بِالْحَقِّ عَلَى ‏ ‏الصَّدَقَةِ ‏ ‏كَالْغَازِي فِي سَبِيلِ اللَّهِ حَتَّى يَرْجِعَ إِلَى بَيْتِهِ ‏","","",""],[16648,16648,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْن لَبِيدٍ ‏ ‏عَنْ ‏ ‏بَعْضِ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْفِرُوا ‏ ‏بِالْفَجْرِ فَإِنَّهُ أَعْظَمُ لِلْأَجْرِ ‏","","",""],[16649,16649,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ عَبْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ سَأَلْتُ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏كِرَاءِ ‏ ‏الْمَزَارِعِ ‏ ‏فَقَالَ أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏أَنَّ ‏ ‏عَمَّيْهِ ‏ ‏وَكَانَا قَدْ شَهِدَا ‏ ‏بَدْرًا ‏ ‏أَخْبَرَاهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏كِرَاءِ ‏ ‏الْمَزَارِعِ ‏","","",""],[16650,16650,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رِشْدِينُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَيُّوبَ الْغَافِقِيِّ ‏ ‏عَنْ ‏ ‏بَعْضِ وَلَدِ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏نَادَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا عَلَى بَطْنِ امْرَأَتِي فَقُمْتُ وَلَمْ أُنْزِلْ فَاغْتَسَلْتُ وَخَرَجْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْتُهُ أَنَّكَ دَعَوْتَنِي وَأَنَا عَلَى بَطْنِ امْرَأَتِي فَقُمْتُ وَلَمْ أُنْزِلْ فَاغْتَسَلْتُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا عَلَيْكَ ‏ ‏الْمَاءُ ‏ ‏مِنْ ‏ ‏الْمَاءِ ‏ ‏قَالَ ‏ ‏رَافِعٌ ‏ ‏ثُمَّ أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ ذَلِكَ بِالْغُسْلِ ‏","","",""],[16651,16651,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏أَبِي النَّجَاشِيِّ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏قَالَ ‏ ‏كُنَّا نُصَلِّي الْعَصْرَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ نَنْحَرُ ‏ ‏الْجَزُورَ ‏ ‏فَنُقَسِّمُهُ عَشَرَةَ أَجْزَاءٍ ثُمَّ نَطْبُخُ فَنَأْكُلُ لَحْمًا نَضِيجًا قَبْلَ أَنْ نُصَلِّيَ الْمَغْرِبَ ‏","","",""],[16652,16652,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ عُتْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءٌ أَبُو النَّجَاشِيِّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏قَالَ ‏ ‏لَقِيَنِي عَمِّي ‏ ‏ظُهَيْرُ بْنُ رَافِعٍ ‏ ‏فَقَالَ يَا ابْنَ أَخِي قَدْ نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَمْرٍ كَانَ بِنَا رَافِقًا قَالَ فَقُلْتُ مَا هُوَ يَا عَمُّ قَالَ ‏ ‏نَهَانَا أَنْ ‏ ‏نُكْرِيَ ‏ ‏مَحَاقِلَنَا ‏ ‏يَعْنِي أَرْضَنَا الَّتِي ‏ ‏بِصِرَارٍ ‏ ‏قَالَ قُلْتُ أَيْ عَمُّ طَاعَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَقُّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ تُكْرُوهَا قَالَ ‏ ‏بِالْجَدَاوِلِ ‏ ‏الرُّبِّ ‏ ‏وَبِالْأَصَوَاعِ ‏ ‏مِنْ الشَّعِيرِ قَالَ فَلَا تَفْعَلُوا ازْرَعُوهَا ‏ ‏أَوْ أَزْرِعُوهَا ‏ ‏قَالَ فَبِعْنَا أَمْوَالَنَا ‏ ‏بِصِرَارٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَأَلْتُ أَبِي عَنْ أَحَادِيثِ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏مَرَّةً يَقُولُ نَهَانَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَرَّةً يَقُولُ عَنْ ‏ ‏عَمَّيْهِ ‏ ‏فَقَالَ كُلُّهَا صِحَاحٌ وَأَحَبُّهَا إِلَيَّ حَدِيثُ ‏ ‏أَيُّوبَ ‏","","",""],[16653,16653,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَالِكٍ ‏ ‏أَنَّ أُخْتَ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏نَذَرَتْ أَنْ تَحُجَّ مَاشِيَةً فَسَأَلَ ‏ ‏عُقْبَةُ ‏ ‏عَنْ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مُرْهَا فَلْتَرْكَبْ فَظَنَّ أَنَّهُ لَمْ يَفْهَمْ عَنْهُ فَلَمَّا خَلَا مَنْ كَانَ عِنْدَهُ عَادَ فَسَأَلَهُ فَقَالَ مُرْهَا فَلْتَرْكَبْ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ عَنْ تَعْذِيبِ أُخْتِكَ نَفْسَهَا لَغَنِيٌّ ‏","","",""],[16654,16654,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏عُهْدَةَ ‏ ‏بَعْدَ أَرْبَعٍ ‏","","",""],[16655,16655,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَرْثَدِ بْنِ عَبْدِ اللَّهِ الْيَزَنِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَغْرِبَ وَعَلَيْهِ ‏ ‏فَرُّوجُ ‏ ‏حَرِيرٍ ‏ ‏وَهُوَ الْقَبَاءُ فَلَمَّا قَضَى صَلَاتَهُ نَزَعَهُ نَزْعًا عَنِيفًا وَقَالَ إِنَّ هَذَا لَا يَنْبَغِي لِلْمُتَّقِينَ ‏","","",""],[16656,16656,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ شِمَاسَةَ التُّجِيبِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ صَاحِبُ ‏ ‏مَكْسٍ ‏ ‏يَعْنِي ‏ ‏الْعَشَّارَ ‏","","",""],[16657,16657,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَرْثَدِ بْنِ عَبْدِ اللَّهِ الْيَزَنِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي رَاكِبٌ غَدًا إِلَى ‏ ‏يَهُودَ ‏ ‏فَلَا تَبْدَءُوهُمْ بِالسَّلَامِ فَإِذَا سَلَّمُوا عَلَيْكُمْ فَقُولُوا وَعَلَيْكُمْ ‏ ‏خَالَفَهُ ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جَعْفَرٍ ‏ ‏وَابْنُ لَهِيعَةَ ‏ ‏قَالَا عَنْ ‏ ‏أَبِي بَصْرَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏أَبُو بَصْرَةَ ‏ ‏يَعْنِي فِي حَدِيثِ ‏ ‏ابْنِ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏","","",""],[16658,16658,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جَابِرٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏بَيْنَا أَنَا أَقُودُ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏نَقَبٍ ‏ ‏مِنْ تِلْكَ ‏ ‏النِّقَابِ ‏ ‏إِذْ قَالَ لِي يَا ‏ ‏عُقْبَةُ ‏ ‏أَلَا تَرْكَبُ قَالَ فَأَجْلَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أَرْكَبَ مَرْكَبَهُ ثُمَّ قَالَ يَا ‏ ‏عُقَيْبُ ‏ ‏أَلَا تَرْكَبُ قَالَ فَأَشْفَقْتُ أَنْ تَكُونَ مَعْصِيَةً قَالَ فَنَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَكِبْتُ ‏ ‏هُنَيَّةً ‏ ‏ثُمَّ رَكِبَ ثُمَّ قَالَ يَا ‏ ‏عُقَيْبُ ‏ ‏أَلَا أُعَلِّمُكَ سُورَتَيْنِ مِنْ خَيْرِ سُورَتَيْنِ قَرَأَ بِهِمَا النَّاسُ قَالَ قُلْتُ بَلَى يَا رَسُولَ اللَّهِ قَالَ فَأَقْرَأَنِي ‏ ‏قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ‏ ‏وَقُلْ أَعُوذُ بِرَبِّ النَّاسِ ‏ ‏ثُمَّ أُقِيمَتْ الصَّلَاةُ فَتَقَدَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَرَأَ بِهِمَا ثُمَّ مَرَّ بِي قَالَ كَيْفَ رَأَيْتَ يَا ‏ ‏عُقَيْبُ ‏ ‏اقْرَأْ بِهِمَا كُلَّمَا نِمْتَ وَكُلَّمَا قُمْتَ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏هُوَ ‏ ‏عُقْبَةُ بْنُ عَامِرِ بْنِ عَابِسٍ ‏ ‏وَقَالَ ‏ ‏ابْنُ عَبْسٍ الْجُهَنِيُّ ‏","","",""],[16659,16659,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏أَنَّ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏ابْنَ عَابِسٍ الْجُهَنِيَّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ يَا ‏ ‏ابْنَ عَابِسٍ ‏ ‏أَلَا أُخْبِرُكَ بِأَفْضَلِ مَا تَعَوَّذَ الْمُتَعَوِّذُونَ قَالَ قُلْتُ بَلَى فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ‏ ‏وَقُلْ أَعُوذُ بِرَبِّ النَّاسِ ‏ ‏هَاتَيْنِ السُّورَتَيْنِ ‏","","",""],[16660,16660,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عُشَّانَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ أَثْكَلَ ثَلَاثَةً مِنْ ‏ ‏صُلْبِهِ ‏ ‏فَاحْتَسَبَهُمْ عَلَى اللَّهِ عَزَّ وَجَلَّ ‏ ‏فَقَالَ ‏ ‏أَبُو عُشَّانَةَ ‏ ‏مَرَّةً فِي سَبِيلِ اللَّهِ وَلَمْ يَقُلْهَا مَرَّةً أُخْرَى ‏ ‏وَجَبَتْ لَهُ الْجَنَّةُ ‏","","",""],[16661,16661,"","","‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُنْزِلَتْ عَلَيَّ سُورَتَانِ فَتَعَوَّذُوا بِهِنَّ فَإِنَّهُ لَمْ يُتَعَوَّذْ بِمِثْلِهِنَّ ‏ ‏يَعْنِي الْمُعَوِّذَتَيْنِ ‏","","",""],[16662,16662,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَّامٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الْأَزْرَقِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُدْخِلُ الثَّلَاثَةَ بِالسَّهْمِ الْوَاحِدِ الْجَنَّةَ صَانِعَهُ يَحْتَسِبُ فِي صَنْعَتِهِ الْخَيْرَ ‏ ‏وَالْمُمِدَّ ‏ ‏بِهِ وَالرَّامِيَ بِهِ وَقَالَ ارْمُوا وَارْكَبُوا وَأَنْ تَرْمُوا أَحَبُّ إِلَيَّ مِنْ أَنْ تَرْكَبُوا وَإِنَّ كُلَّ شَيْءٍ ‏ ‏يَلْهُو بِهِ الرَّجُلُ بَاطِلٌ إِلَّا رَمْيَةَ الرَّجُلِ بِقَوْسِهِ وَتَأْدِيبَهُ فَرَسَهُ وَمُلَاعَبَتَهُ امْرَأَتَهُ فَإِنَّهُنَّ مِنْ الْحَقِّ وَمَنْ نَسِيَ الرَّمْيَ بَعْدَمَا عُلِّمَهُ فَقَدْ كَفَرَ الَّذِي عُلِّمَهُ ‏","","",""],[16663,16663,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدٌ ‏ ‏مَوْلَى ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏كَعْبُ بْنُ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ مَرْثَدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَفَّارَةُ النَّذْرِ كَفَّارَةُ الْيَمِينِ ‏","","",""],[16664,16664,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَرْثَدِ بْنِ عَبْدِ اللَّهِ الْيَزَنِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَحَقَّ الشُّرُوطِ أَنْ يُوَفَّى بِهِ مَا اسْتَحْلَلْتُمْ بِهِ الْفُرُوجَ ‏","","",""],[16665,16665,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏قَيْسٌ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُنْزِلَتْ ‏ ‏عَلَيَّ آيَاتٌ لَمْ يُرَ مِثْلُهُنَّ ‏ ‏قُلْ أَعُوذُ بِرَبِّ النَّاسِ ‏ ‏إِلَى آخِرِ السُّورَةِ ‏ ‏وَقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ‏ ‏إِلَى آخِرِ السُّورَةِ ‏","","",""],[16666,16666,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ الدَّسْتُوَائِيِّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏بَعْجَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَسَمَ ضَحَايَا بَيْنَ أَصْحَابِهِ فَأَصَابَ ‏ ‏عُقْبَةُ بْنُ عَامِرٍ ‏ ‏جَذَعَةً فَسَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْهَا فَقَالَ ضَحِّ بِهَا ‏","","",""],[16667,16667,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ الْأَسْلَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عَلِيٍّ الْهَمْدَانِيِّ ‏ ‏قَالَ ‏ ‏خَرَجْتُ فِي سَفَرٍ وَمَعَنَا ‏ ‏عُقْبَةُ بْنُ عَامِرٍ ‏ ‏قَالَ فَقُلْنَا لَهُ إِنَّكَ يَرْحَمُكَ اللَّهُ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأُمَّنَا فَقَالَ لَا إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَمَّ النَّاسَ فَأَصَابَ الْوَقْتَ وَأَتَمَّ الصَّلَاةَ فَلَهُ وَلَهُمْ وَمَنْ انْتَقَصَ مِنْ ذَلِكَ شَيْئًا فَعَلَيْهِ وَلَا عَلَيْهِمْ ‏","","",""],[16668,16668,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الرُّعَيْنِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَالِكٍ الْيَحْصَبِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏أَنَّ أُخْتَهُ نَذَرَتْ أَنْ تَمْشِيَ حَافِيَةً غَيْرَ مُخْتَمِرَةٍ فَسَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ لَا يَصْنَعُ بِشَقَاءِ أُخْتِكَ شَيْئًا مُرْهَا فَلْتَخْتَمِرْ وَلْتَرْكَبْ وَلْتَصُمْ ثَلَاثَةَ أَيَّامٍ ‏","","",""],[16669,16669,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْخَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مَثَلَ الَّذِي يَعْمَلُ السَّيِّئَاتِ ثُمَّ يَعْمَلُ الْحَسَنَاتِ كَمَثَلِ رَجُلٍ كَانَتْ عَلَيْهِ دِرْعٌ ضَيِّقَةٌ قَدْ خَنَقَتْهُ ثُمَّ عَمِلَ حَسَنَةً فَانْفَكَّتْ حَلْقَةٌ ثُمَّ عَمِلَ حَسَنَةً أُخْرَى فَانْفَكَّتْ حَلْقَةٌ أُخْرَى حَتَّى يَخْرُجَ إِلَى الْأَرْضِ ‏","","",""],[16670,16670,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَرْمَلَةُ بْنُ عِمْرَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ الْمَلِكِ بْنِ مُلَيْلٍ السَّلِيحِيُّ ‏ ‏وَهُمْ إِلَى ‏ ‏قُضَاعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏جَالِسًا قَرِيبًا مِنْ الْمِنْبَرِ يَوْمَ الْجُمُعَةِ فَخَرَجَ ‏ ‏مُحَمَّدُ بْنُ أَبِي حُذَيْفَةَ ‏ ‏فَاسْتَوَى عَلَى الْمِنْبَرِ فَخَطَبَ النَّاسَ ثُمَّ قَرَأَ عَلَيْهِمْ سُورَةً مِنْ الْقُرْآنِ قَالَ وَكَانَ مِنْ أَقْرَإِ النَّاسِ قَالَ فَقَالَ ‏ ‏عُقْبَةُ بْنُ عَامِرٍ ‏ ‏صَدَقَ اللَّهُ وَرَسُولُهُ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيَقْرَأَنَّ الْقُرْآنَ رِجَالٌ لَا يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ الرَّمِيَّةِ ‏","","",""],[16671,16671,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏أَخْبَرَنِي ‏ ‏يَزِيدُ بْنُ عَمْرٍو الْمَعَافِرِيُّ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَاعِيًا فَاسْتَأْذَنْتُهُ أَنْ نَأْكُلَ مِنْ ‏ ‏الصَّدَقَةِ ‏ ‏فَأَذِنَ لَنَا ‏","","",""],[16672,16672,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رِشْدِينُ يَعْنِي ابْنَ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمْرٌو يَعْنِي ابْنَ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي عُشَّانَةَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يُخْبِرُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَمْنَعُ أَهْلَ الْحِلْيَةِ وَالْحَرِيرِ وَيَقُولُ ‏ ‏إِنْ كُنْتُمْ تُحِبُّونَ حِلْيَةَ الْجَنَّةِ وَحَرِيرَهَا فَلَا تَلْبَسُوهَا فِي الدُّنْيَا ‏","","",""],[16673,16673,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رِشْدِينُ يَعْنِي ابْنَ سَعْدٍ أَبُو الْحَجَّاجِ الْمَهْرِيُّ ‏ ‏عَنْ ‏ ‏حَرْمَلَةَ بْنِ عِمْرَانَ التُّجِيبِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا رَأَيْتَ اللَّهَ يُعْطِي الْعَبْدَ مِنْ الدُّنْيَا عَلَى مَعَاصِيهِ مَا يُحِبُّ فَإِنَّمَا هُوَ اسْتِدْرَاجٌ ثُمَّ تَلَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏فَلَمَّا نَسُوا مَا ذُكِّرُوا بِهِ فَتَحْنَا عَلَيْهِمْ أَبْوَابَ كُلِّ شَيْءٍ حَتَّى إِذَا فَرِحُوا بِمَا أُوتُوا أَخَذْنَاهُمْ بَغْتَةً فَإِذَا هُمْ ‏ ‏مُبْلِسُونَ ‏ }","","",""],[16674,16674,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي عُشَّانَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَعْجَبُ رَبُّكُمْ مِنْ رَاعِي ‏ ‏غَنَمٍ ‏ ‏فِي ‏ ‏شَظِيَّةٍ ‏ ‏يُؤَذِّنُ بِالصَّلَاةِ وَيُقِيمُ ‏","","",""],[16675,16675,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏الْحَارِثِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَنْسَابَكُمْ هَذِهِ لَيْسَتْ ‏ ‏بِسِبَابٍ ‏ ‏عَلَى أَحَدٍ وَإِنَّمَا أَنْتُمْ وَلَدُ ‏ ‏آدَمَ ‏ ‏طَفُّ ‏ ‏الصَّاعِ لَمْ تَمْلَئُوهُ لَيْسَ لِأَحَدٍ فَضْلٌ إِلَّا بِالدِّينِ أَوْ عَمَلٍ صَالِحٍ حَسْبُ الرَّجُلِ أَنْ يَكُونَ فَاحِشًا ‏ ‏بَذِيًّا ‏ ‏بَخِيلًا جَبَانًا ‏","","",""],[16676,16676,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْعَلَاءِ الْحَسَنُ بْنُ سَوَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏وَرَبِيعَةُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ الْخَوْلَانِيِّ ‏ ‏وَعَبْدُ الْوَهَّابِ بْنُ بُخْتٍ ‏ ‏عَنْ ‏ ‏اللَّيْثِ بْنِ سُلَيْمٍ الْجُهَنِيِّ ‏ ‏كُلُّهُمْ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عُقْبَةُ ‏ ‏كُنَّا نَخْدُمُ أَنْفُسَنَا وَكُنَّا نَتَدَاوَلُ رَعِيَّةَ الْإِبِلِ بَيْنَنَا فَأَصَابَنِي رَعِيَّةُ الْإِبِلِ فَرَوَّحْتُهَا بِعَشِيٍّ فَأَدْرَكْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ قَائِمٌ يُحَدِّثُ النَّاسَ فَأَدْرَكْتُ مِنْ حَدِيثِهِ وَهُوَ يَقُولُ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ يَتَوَضَّأُ فَيُسْبِغُ الْوُضُوءَ ثُمَّ يَقُومُ فَيَرْكَعُ رَكْعَتَيْنِ يُقْبِلُ عَلَيْهِمَا بِقَلْبِهِ وَوَجْهِهِ إِلَّا وَجَبَتْ لَهُ الْجَنَّةُ وَغُفِرَ لَهُ ‏ ‏قَالَ ‏ ‏فَقُلْتُ لَهُ ‏ ‏مَا أَجْوَدَ هَذَا قَالَ فَقَالَ قَائِلٌ بَيْنَ يَدِي الَّتِي كَانَ قَبْلَهَا يَا ‏ ‏عُقْبَةُ ‏ ‏أَجْوَدُ مِنْهَا فَنَظَرْتُ فَإِذَا ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏قَالَ فَقُلْتُ وَمَا هِيَ يَا ‏ ‏أَبَا حَفْصٍ ‏ ‏قَالَ إِنَّهُ قَالَ قَبْلَ أَنْ تَأْتِيَ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ يَتَوَضَّأُ فَيُسْبِغُ الْوُضُوءَ ثُمَّ يَقُولُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ إِلَّا فُتِحَتْ لَهُ أَبْوَابُ الْجَنَّةِ الثَّمَانِيَةِ يَدْخُلُ مِنْ أَيِّهَا شَاءَ ‏","","",""],[16677,16677,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ أَبِي أَيُّوبَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثٌ إِنْ كَانَ فِي شَيْءٍ شِفَاءٌ فَفِي ‏ ‏شَرْطَةِ ‏ ‏مُحْجِمٍ ‏ ‏أَوْ شَرْبَةِ عَسَلٍ أَوْ كَيَّةٍ تُصِيبُ أَلَمًا وَأَنَا أَكْرَهُ الْكَيَّ وَلَا أُحِبُّهُ ‏","","",""],[16678,16678,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ ‏ ‏أَنَّ ‏ ‏أَبَا الْخَيْرِ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ لَيْسَ مِنْ عَمَلِ يَوْمٍ إِلَّا وَهُوَ يُخْتَمُ عَلَيْهِ فَإِذَا مَرِضَ الْمُؤْمِنُ قَالَتْ الْمَلَائِكَةُ يَا رَبَّنَا عَبْدُكَ فُلَانٌ قَدْ حَبَسْتَهُ فَيَقُولُ الرَّبُّ عَزَّ وَجَلَّ ‏ ‏اخْتِمُوا لَهُ عَلَى مِثْلِ عَمَلِهِ حَتَّى يَبْرَأَ أَوْ يَمُوتَ ‏","","",""],[16679,16679,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ عَبْدُ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُوسَى بْنُ عَلِيٍّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَعَلَّمُوا كِتَابَ اللَّهِ وَتَعَاهَدُوهُ وَتَغَنُّوا بِهِ فَوَالَّذِي نَفْسِي بِيَدِهِ لَهُوَ أَشَدُّ ‏ ‏تَفَلُّتًا ‏ ‏مِنْ ‏ ‏الْمَخَاضِ ‏ ‏فِي الْعُقُلِ ‏","","",""],[16680,16680,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو قَبِيلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا أَخَافُ عَلَى أُمَّتِي الْكِتَابَ وَاللَّبَنَ قَالَ قِيلَ يَا رَسُولَ اللَّهِ مَا بَالُ الْكِتَابِ قَالَ يَتَعَلَّمُهُ الْمُنَافِقُونَ ثُمَّ يُجَادِلُونَ بِهِ الَّذِينَ آمَنُوا فَقِيلَ وَمَا بَالُ اللَّبَنِ قَالَ أُنَاسٌ يُحِبُّونَ اللَّبَنَ فَيَخْرُجُونَ مِنْ الْجَمَاعَاتِ وَيَتْرُكُونَ الْجُمُعَاتِ ‏","","",""],[16681,16681,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏كَعْبُ بْنُ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ شِمَاسَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَفَّارَةُ النَّذْرِ كَفَّارَةُ الْيَمِينِ ‏","","",""],[16682,16682,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عَمْرٍو الْمَعَافِرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ زُرْعَةَ الْمَعَافِرِيُّ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تُخِيفُوا أَنْفُسَكُمْ بَعْدَ أَمْنِهَا قَالُوا وَمَا ذَاكَ يَا رَسُولَ اللَّهِ قَالَ الدَّيْنُ ‏","","",""],[16683,16683,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏أَنَّ ‏ ‏أَبَا سَلَّامٍ ‏ ‏حَدَّثَهُ قَالَ حَدَّثَنِي ‏ ‏خَالِدُ بْنُ زَيْدٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عُقْبَةُ ‏ ‏يَأْتِينِي فَيَقُولُ اخْرُجْ بِنَا نَرْمِي فَأَبْطَأْتُ عَلَيْهِ ذَاتَ يَوْمٍ ‏ ‏أَوْ تَثَاقَلْتُ ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُدْخِلُ بِالسَّهْمِ الْوَاحِدِ ثَلَاثَةً الْجَنَّةَ صَانِعَهُ الْمُحْتَسِبَ فِيهِ الْخَيْرَ وَالرَّامِيَ بِهِ ‏ ‏وَمُنْبِلَهُ ‏ ‏فَارْمُوا وَارْكَبُوا وَلَأَنْ تَرْمُوا أَحَبُّ إِلَيَّ مَنْ أَنْ تَرْكَبُوا وَلَيْسَ مِنْ اللَّهْوِ إِلَّا ثَلَاثٌ مُلَاعَبَةُ الرَّجُلِ امْرَأَتَهُ وَتَأْدِيبُهُ فَرَسَهُ وَرَمْيُهُ بِقَوْسِهِ وَمَنْ عَلَّمَهُ اللَّهُ الرَّمْيَ فَتَرَكَهُ رَغْبَةً عَنْهُ فَنِعْمَةً كَفَرَهَا ‏","","",""],[16684,16684,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏مِشْرَحِ بْنِ هَاعَانَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْرَأْ ‏ ‏بِالْمُعَوِّذَتَيْنِ ‏ ‏فَإِنَّكَ لَنْ تَقْرَأَ بِمِثْلِهِمَا ‏","","",""],[16685,16685,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَطَّافٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏جُهَيْنَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّهَا سَتَكُونُ عَلَيْكُمْ أَئِمَّةٌ مِنْ بَعْدِي فَإِنْ صَلَّوْا الصَّلَاةَ لِوَقْتِهَا فَأَتِمُّوا الرُّكُوعَ وَالسُّجُودَ فَهِيَ لَكُمْ وَلَهُمْ وَإِنْ لَمْ يُصَلُّوا الصَّلَاةَ لِوَقْتِهَا وَلَمْ يُتِمُّوا رُكُوعَهَا وَلَا سُجُودَهَا فَهِيَ لَكُمْ وَعَلَيْهِمْ ‏","","",""],[16686,16686,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ إِبْرَاهِيمَ الرَّازِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ الْفَضْلِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَرْثَدِ بْنِ عَبْدِ اللَّهِ الْيَزَنِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْرَأْ الْآيَتَيْنِ مِنْ آخِرِ سُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏فَإِنِّي أُعْطِيتُهُمَا مِنْ تَحْتِ الْعَرْشِ ‏","","",""],[16687,16687,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ يَعْنِي ابْنَ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏كَعْبُ بْنُ عَلْقَمَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ شِمَاسَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏كَفَّارَةُ النَّذْرِ كَفَّارَةُ الْيَمِينِ ‏","","",""],[16688,16688,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخِفَافُ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ذَكَرَ أَنَّ ‏ ‏قَيْسًا الْجُذَامِيَّ ‏ ‏حَدَّثَهُ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَعْتَقَ رَقَبَةً مُؤْمِنَةً فَهِيَ فِكَاكُهُ مِنْ النَّارِ ‏","","",""],[16689,16689,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ الْمِصْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ شِمَاسَةَ التُّجِيبِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ الْجُهَنِيَّ ‏ ‏يَقُولُ ‏ ‏وَهُوَ عَلَى مِنْبَرِ ‏ ‏مِصْرَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَحِلُّ لِامْرِئٍ يَبِيعُ عَلَى بَيْعِ أَخِيهِ حَتَّى ‏ ‏يَذَرَهُ ‏","","",""],[16690,16690,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ شِمَاسَةَ التُّجِيبِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَحِلُّ لِامْرِئٍ مُسْلِمٍ يَخْطُبُ عَلَى خِطْبَةِ أَخِيهِ حَتَّى يَتْرُكَ وَلَا يَبِيعُ عَلَى بَيْعِ أَخِيهِ حَتَّى يَتْرُكَ ‏","","",""],[16691,16691,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ الْمِصْرِيُّ ‏ ‏عَنْ ‏ ‏مَرْثَدِ بْنِ عَبْدِ اللَّهِ الْيَزَنِيِّ ‏ ‏وَيَزَنُ ‏ ‏بَطْنٌ مِنْ ‏ ‏حِمْيَرَ ‏ ‏قَالَ ‏ ‏قَدِمَ عَلَيْنَا ‏ ‏أَبُو أَيُّوبَ خَالِدُ بْنُ زَيْدٍ الْأَنْصَارِيُّ ‏ ‏صَاحِبُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِصْرَ ‏ ‏غَازِيًا وَكَانَ ‏ ‏عُقْبَةُ بْنُ عَامِرِ بْنِ عَبْسٍ الْجُهَنِيُّ ‏ ‏أَمَّرَهُ عَلَيْنَا ‏ ‏مُعَاوِيَةُ بْنُ أَبِي سُفْيَانَ ‏ ‏قَالَ فَحَبَسَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏بِالْمَغْرِبِ فَلَمَّا صَلَّى قَامَ إِلَيْهِ ‏ ‏أَبُو أَيُّوبَ الْأَنْصَارِيُّ ‏ ‏فَقَالَ لَهُ يَا ‏ ‏عُقْبَةُ ‏ ‏أَهَكَذَا رَأَيْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْمَغْرِبَ أَمَا سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَزَالُ أُمَّتِي بِخَيْرٍ ‏ ‏أَوْ عَلَى الْفِطْرَةِ ‏ ‏مَا لَمْ يُؤَخِّرُوا الْمَغْرِبَ حَتَّى تَشْتَبِكَ النُّجُومُ قَالَ فَقَالَ بَلَى قَالَ فَمَا حَمَلَكَ عَلَى مَا صَنَعْتَ قَالَ شُغِلْتُ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏أَمَا وَاللَّهِ مَا بِي إِلَّا أَنْ يَظُنَّ النَّاسُ أَنَّكَ رَأَيْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ هَذَا ‏","","",""],[16692,16692,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ سَوَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ جُعْثُلٍ الْقِتْبَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمٍ الْجَيْشَانِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّ أُخْتَ ‏ ‏عُقْبَةَ ‏ ‏نَذَرَتْ فِي ابْنٍ لَهَا لَتَحُجَّنَّ حَافِيَةً بِغَيْرِ خِمَارٍ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏تَحُجُّ رَاكِبَةً مُخْتَمِرَةً وَلْتَصُمْ ‏","","",""],[16693,16693,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏كَعْبُ بْنُ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏كَثِيرٍ ‏ ‏مَوْلَى ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سَتَرَ مُؤْمِنًا كَانَ كَمَنْ أَحْيَا ‏ ‏مَوْءُودَةً ‏ ‏مِنْ قَبْرِهَا ‏","","",""],[16694,16694,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏وَمُوسَى بْنُ دَاوُدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏كَعْبُ بْنُ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏مَوْلًى ‏ ‏لِعُقْبَةَ بْنِ عَامِرٍ ‏ ‏يُقَالُ لَهُ ‏ ‏كَثِيرٌ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏فَأَخْبَرْتُهُ أَنَّ لَنَا جِيرَانًا يَشْرَبُونَ الْخَمْرَ قَالَ دَعْهُمْ ثُمَّ جَاءَهُ فَقَالَ أَلَا أَدْعُو عَلَيْهِمْ الشُّرَطُ فَقَالَ ‏ ‏عُقْبَةُ ‏ ‏وَيْحَكَ دَعْهُمْ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مِنْ رَأَى عَوْرَةً فَسَتَرَهَا كَانَ كَمَنْ أَحْيَا ‏ ‏مَوْءُودَةً ‏ ‏مِنْ قَبْرِهَا ‏","","",""],[16695,16695,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُبَارَكٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَرْمَلَةُ بْنُ عِمْرَانَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏يَزِيدَ بْنَ أَبِي حَبِيبٍ ‏ ‏يُحَدِّثُ أَنَّ ‏ ‏أَبَا الْخَيْرِ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏كُلُّ امْرِئٍ فِي ‏ ‏ظِلِّ صَدَقَتِهِ حَتَّى يُفْصَلَ بَيْنَ النَّاسِ ‏ ‏أَوْ قَالَ يُحْكَمَ بَيْنَ النَّاسِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏وَكَانَ ‏ ‏أَبُو الْخَيْرِ ‏ ‏لَا يُخْطِئُهُ يَوْمٌ إِلَّا تَصَدَّقَ فِيهِ بِشَيْءٍ وَلَوْ كَعْكَةً أَوْ بَصَلَةً أَوْ كَذَا ‏","","",""],[16696,16696,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ الْبَاهِلِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏لَقِيتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَابْتَدَأْتُهُ ‏ ‏فَأَخَذْتُ بِيَدِهِ قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏مَا نَجَاةُ ‏ ‏هَذَا الْأَمْرِ ‏ ‏قَالَ يَا ‏ ‏عُقْبَةُ ‏ ‏احْرُسْ لِسَانَكَ وَلْيَسَعْكَ بَيْتُكَ وَابْكِ عَلَى خَطِيئَتِكَ قَالَ ثُمَّ لَقِيَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَابْتَدَأَنِي ‏ ‏فَأَخَذَ بِيَدِي فَقَالَ يَا ‏ ‏عُقْبَةُ بْنُ عَامِرٍ ‏ ‏أَلَا أُعَلِّمُكَ خَيْرَ ثَلَاثِ سُوَرٍ أُنْزِلَتْ فِي التَّوْرَاةِ وَالْإِنْجِيلِ وَالزَّبُورِ وَالْفُرْقَانِ الْعَظِيمِ قَالَ قُلْتُ بَلَى جَعَلَنِي اللَّهُ فِدَاكَ قَالَ فَأَقْرَأَنِي ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏وَقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ‏ ‏وَقُلْ أَعُوذُ بِرَبِّ النَّاسِ ‏ ‏ثُمَّ قَالَ يَا ‏ ‏عُقْبَةُ ‏ ‏لَا ‏ ‏تَنْسَاهُنَّ وَلَا تَبِيتَ لَيْلَةً حَتَّى تَقْرَأَهُنَّ قَالَ فَمَا نَسِيتُهُنَّ مِنْ مُنْذُ قَالَ لَا ‏ ‏تَنْسَاهُنَّ وَمَا بِتُّ لَيْلَةً قَطُّ حَتَّى أَقْرَأَهُنَّ قَالَ ‏ ‏عُقْبَةُ ‏ ‏ثُمَّ لَقِيتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَابْتَدَأْتُهُ ‏ ‏فَأَخَذْتُ بِيَدِهِ فَقُلْتُ يَا رَسُولَ اللَّهِ أَخْبِرْنِي بِفَوَاضِلِ الْأَعْمَالِ فَقَالَ يَا ‏ ‏عُقْبَةُ ‏ ‏صِلْ مَنْ قَطَعَكَ وَأَعْطِ مَنْ حَرَمَكَ وَأَعْرِضْ عَمَّنْ ظَلَمَكَ ‏","","",""],[16697,16697,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَّامٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ زَيْدٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏وَكَانَ رَجُلًا يُحِبُّ الرَّمْيَ إِذَا خَرَجَ خَرَجَ بِي مَعَهُ فَدَعَانِي يَوْمًا ‏ ‏فَأَبْطَأْتُ ‏ ‏عَلَيْهِ فَقَالَ تَعَالَ أَقُولُ لَكَ مَا قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا حَدَّثَنِي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُدْخِلُ بِالسَّهْمِ الْوَاحِدِ ثَلَاثَةَ نَفَرٍ الْجَنَّةَ صَانِعَهُ الْمُحْتَسِبَ فِي صَنَعْتِهِ الْخَيْرَ وَالرَّامِيَ بِهِ ‏ ‏وَمُنْبِلَهُ ‏ ‏وَقَالَ ارْمُوا وَارْكَبُوا وَلَأَنْ تَرْمُوا أَحَبُّ إِلَيَّ مِنْ أَنْ تَرْكَبُوا وَلَيْسَ مِنْ اللَّهْوِ إِلَّا ثَلَاثٌ تَأْدِيبُ الرَّجُلِ فَرَسَهُ وَمُلَاعَبَتُهُ امْرَأَتَهُ وَرَمْيُهُ بِقَوْسِهِ وَمَنْ تَرَكَ الرَّمْيَ بَعْدَمَا عُلِّمَهُ رَغْبَةً عَنْهُ فَإِنَّهَا نِعْمَةٌ تَرَكَهَا ‏","","",""],[16698,16698,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَّامٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ عُلِّمَ الرَّمْيَ ثُمَّ تَرَكَهُ بَعْدَمَا عُلِّمَهُ فَهِيَ نِعْمَةٌ كَفَرَهَا ‏","","",""],[16699,16699,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ سَلَّامٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ الْأَزْرَقِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عُقْبَةُ بْنُ عَامِرٍ الْجُهَنِيُّ ‏ ‏يَخْرُجُ ‏ ‏فَيَرْمِي كُلَّ يَوْمٍ وَكَانَ يَسْتَتْبِعُهُ فَكَأَنَّهُ كَادَ أَنْ يَمَلَّ فَقَالَ أَلَا أُخْبِرُكَ بِمَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ بَلَى قَالَ سَمِعْتُهُ يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُدْخِلُ بِالسَّهْمِ الْوَاحِدِ ثَلَاثَةَ نَفَرٍ الْجَنَّةَ صَاحِبَهُ الَّذِي يَحْتَسِبُ فِي صَنْعَتِهِ الْخَيْرَ وَالَّذِي يُجَهِّزُ بِهِ فِي سَبِيلِ اللَّهِ وَالَّذِي يَرْمِي بِهِ فِي سَبِيلِ اللَّهِ وَقَالَ ارْمُوا وَارْكَبُوا وَإِنْ تَرْمُوا خَيْرٌ مِنْ أَنْ تَرْكَبُوا وَقَالَ كُلُّ شَيْءٍ ‏ ‏يَلْهُو بِهِ ابْنُ ‏ ‏آدَمَ ‏ ‏فَهُوَ بَاطِلٌ إِلَّا ثَلَاثًا رَمْيَهُ عَنْ قَوْسِهِ وَتَأْدِيبَهُ فَرَسَهُ وَمُلَاعَبَتَهُ أَهْلَهُ فَإِنَّهُنَّ مِنْ الْحَقِّ ‏ ‏قَالَ ‏ ‏فَتُوُفِّيَ ‏ ‏عُقْبَةُ ‏ ‏وَلَهُ بِضْعٌ وَسِتُّونَ ‏ ‏أَوْ بِضْعٌ وَسَبْعُونَ ‏ ‏قَوْسًا مَعَ كُلِّ قَوْسٍ قَرْنٌ وَنَبْلٌ وَأَوْصَى بِهِنَّ فِي سَبِيلِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَّامٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْأَزْرَقِ ‏ ‏أَنَّ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُدْخِلُ بِالسَّهْمِ الْوَاحِدِ ثَلَاثَةً الْجَنَّةَ فَذَكَرَ الْحَدِيثَ ‏","","",""],[16700,16700,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَائِذٍ ‏ ‏رَجُلٍ مِنْ أَهْلِ ‏ ‏الشَّامِ ‏ ‏قَالَ ‏ ‏انْطَلَقَ ‏ ‏عُقْبَةُ بْنُ عَامِرٍ الْجُهَنِيُّ ‏ ‏إِلَى ‏ ‏الْمَسْجِدِ الْأَقْصَى ‏ ‏لِيُصَلِّيَ فِيهِ فَاتَّبَعَهُ نَاسٌ فَقَالَ مَا جَاءَ بِكُمْ قَالُوا صُحْبَتُكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْبَبْنَا أَنْ نَسِيرَ مَعَكَ وَنُسَلِّمَ عَلَيْكَ قَالَ انْزِلُوا فَصَلُّوا فَنَزَلُوا فَصَلَّى وَصَلَّوْا مَعَهُ فَقَالَ حِينَ سَلَّمَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيْسَ مِنْ عَبْدٍ يَلْقَى اللَّهَ عَزَّ وَجَلَّ لَا يُشْرِكُ بِهِ شَيْئًا لَمْ ‏ ‏يَتَنَدَّ ‏ ‏بِدَمٍ حَرَامٍ إِلَّا دَخَلَ مِنْ أَيِّ أَبْوَابِ الْجَنَّةِ شَاءَ ‏","","",""],[16701,16701,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏كَعْبُ بْنُ عَلْقَمَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ شِمَاسَةَ ‏ ‏يَقُولُ ‏ ‏أَتَيْنَا ‏ ‏أَبَا الْخَيْرِ ‏ ‏فَقَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّمَا النَّذْرُ يَمِينٌ كَفَّارَتُهَا كَفَّارَةُ الْيَمِينِ ‏","","",""],[16702,16702,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشْمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏اتَّبَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ رَاكِبٌ فَوَضَعْتُ يَدَيَّ عَلَى ‏ ‏قَدَمَيْهِ فَقُلْتُ ‏ ‏أَقْرِئْنِي مِنْ سُورَةِ ‏ ‏يُوسُفَ ‏ ‏فَقَالَ ‏ ‏لَنْ تَقْرَأَ شَيْئًا أَبْلَغَ عِنْدَ اللَّهِ عَزَّ وَجَلَّ مِنْ ‏ ‏قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ‏","","",""],[16703,16703,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏حَدَّثَنَا ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّهُ ‏ ‏قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُهْدِيَتْ لَهُ بَغْلَةٌ ‏ ‏شَهْبَاءُ ‏ ‏فَرَكِبَهَا فَأَخَذَ ‏ ‏عُقْبَةُ ‏ ‏يَقُودُهَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِعُقْبَةَ ‏ ‏اقْرَأْ فَقَالَ وَمَا أَقْرَأُ يَا رَسُولَ اللَّهِ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْرَأْ ‏ ‏قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ‏ ‏فَأَعَادَهَا عَلَيْهِ حَتَّى قَرَأَهَا فَعَرَفَ أَنِّي لَمْ أَفْرَحْ بِهَا جِدًّا فَقَالَ لَعَلَّكَ تَهَاوَنْتَ بِهَا فَمَا قُمْتَ تُصَلِّي بِشَيْءٍ مِثْلِهَا ‏","","",""],[16704,16704,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وهَاشِمٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏أُهْدِيَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرُّوجُ ‏ ‏حَرِيرٍ فَلَبِسَهُ ثُمَّ صَلَّى فِيهِ ثُمَّ انْصَرَفَ فَنَزَعَهُ نَزْعًا عَنِيفًا شَدِيدًا كَالْكَارِهِ لَهُ ثُمَّ قَالَ ‏ ‏لَا يَنْبَغِي هَذَا لِلْمُتَّقِينَ ‏","","",""],[16705,16705,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ يَوْمًا فَصَلَّى عَلَى أَهْلِ ‏ ‏أُحُدٍ ‏ ‏صَلَاتَهُ عَلَى الْمَيِّتِ ثُمَّ انْصَرَفَ إِلَى الْمِنْبَرِ فَقَالَ ‏ ‏إِنِّي ‏ ‏فَرَطٌ ‏ ‏لَكُمْ وَإِنِّي شَهِيدٌ عَلَيْكُمْ وَإِنِّي وَاللَّهِ لَأَنْظُرُ إِلَى الْحَوْضِ أَلَا وَإِنِّي قَدْ أُعْطِيتُ مَفَاتِيحَ خَزَائِنِ الْأَرْضِ ‏ ‏أَوْ مَفَاتِيحَ الْأَرْضِ ‏ ‏إِنِّي وَاللَّهِ مَا أَخَافُ عَلَيْكُمْ أَنْ تُشْرِكُوا بَعْدِي وَلَكِنِّي أَخَافُ عَلَيْكُمْ أَنْ تَنَافَسُوا فِيهَا ‏","","",""],[16706,16706,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏قُلْنَا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكَ تَبْعَثُنَا فَنَنْزِلُ بِقَوْمٍ لَا ‏ ‏يَقْرُونَا ‏ ‏فَمَا ‏ ‏تَرَى فِي ذَلِكَ فَقَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا نَزَلْتُمْ بِقَوْمٍ فَأَمَرُوا لَكُمْ بِمَا يَنْبَغِي لِلضَّيْفِ فَاقْبَلُوا وَإِنْ لَمْ يَفْعَلُوا فَخُذُوا مِنْهُمْ حَقَّ الضَّيْفِ الَّذِي يَنْبَغِي لَهُمْ ‏","","",""],[16707,16707,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْطَاهُ غَنَمًا فَقَسَمَهَا عَلَى أَصْحَابِهِ ضَحَايَا فَبَقِيَ ‏ ‏عَتُودٌ ‏ ‏مِنْهَا فَذَكَرَهُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ضَحِّ بِهِ ‏","","",""],[16708,16708,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِيَّاكُمْ وَالدُّخُولَ عَلَى النِّسَاءِ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يَا رَسُولَ اللَّهِ أَفَرَأَيْتَ الْحَمْوَ قَالَ الْحَمْوُ الْمَوْتُ ‏","","",""],[16709,16709,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَحْرٍ الضَّمْرِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ الرُّعَيْنِيَّ ‏ ‏يُحَدِّثُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مَالِكٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏أُخْتَهُ نَذَرَتْ أَنْ تَمْشِيَ حَافِيَةً غَيْرَ مُخْتَمِرَةٍ فَذَكَرَ ذَلِكَ ‏ ‏عُقْبَةُ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مُرْ أُخْتَكَ فَلْتَرْكَبْ وَلْتَخْتَمِرْ وَلْتَصُمْ ثَلَاثَةَ أَيَّامٍ ‏","","",""],[16710,16710,"","","‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ عَمْرٍو الْكَلْبِيُّ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَنْكَحَ ‏ ‏الْوَلِيَّانِ ‏ ‏فَهُوَ لِلْأَوَّلِ مِنْهُمَا وَإِذَا بَاعَ مِنْ رَجُلَيْنِ فَهُوَ لِلْأَوَّلِ مِنْهُمَا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏وَإِذَا بَاعَ الرَّجُلُ بَيْعًا مِنْ رَجُلَيْنِ ‏","","",""],[16711,16711,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏مَوْلَى ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَقُودُ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَاقَتَهُ قَالَ فَقَالَ لِي ‏ ‏أَلَا أُعَلِّمُكَ سُورَتَيْنِ لَمْ يُقْرَأْ بِمِثْلِهِمَا قُلْتُ بَلَى فَعَلَّمَنِي ‏ ‏قُلْ أَعُوذُ بِرَبِّ النَّاسِ ‏ ‏وَقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ‏ ‏فَلَمْ يَرَنِي أُعْجِبْتُ بِهِمَا فَلَمَّا نَزَلَ الصُّبْحَ فَقَرَأَ بِهِمَا ثُمَّ قَالَ لِي كَيْفَ رَأَيْتَ يَا ‏ ‏عُقْبَةُ ‏","","",""],[16712,16712,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ السَّخْتِيَانِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏صَلُّوا فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ وَلَا تُصَلُّوا فِي ‏ ‏أَعْطَانِ ‏ ‏الْإِبِلِ ‏ ‏أَوْ مَبَارِكِ الْإِبِلِ ‏ ‏و قَالَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏حَدَّثَنِي ‏ ‏عَاصِمُ بْنُ حَكِيمٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذَلِكَ ‏","","",""],[16713,16713,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏و حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏الضَّحَّاكِ بْنِ مَخْلَدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَرْثَدِ بْنِ عَبْدِ اللَّهِ الْيَزَنِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏أُهْدِيَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرُّوجُ ‏ ‏حَرِيرٍ فَلَبِسَهُ فَصَلَّى فِيهِ بِالنَّاسِ الْمَغْرِبَ فَلَمَّا سَلَّمَ مِنْ صَلَاتِهِ نَزَعَهُ نَزْعًا عَنِيفًا ثُمَّ أَلْقَاهُ فَقُلْنَا يَا رَسُولَ اللَّهِ قَدْ لَبِسْتَهُ وَصَلَّيْتَ فِيهِ قَالَ إِنَّ هَذَا لَا يَنْبَغِي لِلْمُتَّقِينَ ‏","","",""],[16714,16714,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ شِمَاسَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ الْجُهَنِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَدْخُلُ صَاحِبُ ‏ ‏مَكْسٍ ‏ ‏الْجَنَّةَ ‏ ‏يَعْنِي ‏ ‏الْعَشَّارَ ‏","","",""],[16715,16715,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُنْزِلَ عَلَيَّ آيَاتٌ لَمْ أَرَ مِثْلَهُنَّ الْمُعَوِّذَتَيْنِ ثُمَّ قَرَأَهُمَا ‏","","",""],[16716,16716,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ أُمِّي مَاتَتْ وَإِنِّي أُرِيدُ أَنْ أَتَصَدَّقَ عَنْهَا قَالَ أَمَرَتْكَ قَالَ لَا قَالَ فَلَا تَفْعَلْ ‏","","",""],[16717,16717,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏قَيْسٍ الْجُذَامِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَعْتَقَ رَقَبَةً مُسْلِمَةً فَهِيَ فِدَاؤُهُ مِنْ النَّارِ ‏","","",""],[16718,16718,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عُهْدَةُ ‏ ‏الرَّقِيقِ أَرْبَعُ لَيَالٍ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏وَأَهْلُ ‏ ‏الْمَدِينَةِ ‏ ‏يَقُولُونَ ثَلَاثُ لَيَالٍ ‏","","",""],[16719,16719,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏مِشْرَحٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏كُلُّ مَيِّتٍ يُخْتَمُ عَلَى عَمَلِهِ إِلَّا ‏ ‏الْمُرَابِطَ ‏ ‏فِي سَبِيلِ اللَّهِ فَإِنَّهُ ‏ ‏يُجْرَى لَهُ أَجْرُ عَمَلِهِ حَتَّى يُبْعَثَ ‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ فِيهِ وَيُؤَمَّنُ مِنْ فَتَّانِ الْقَبْرِ ‏","","",""],[16720,16720,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏أَظُنُّهُ ‏ ‏عَنْ ‏ ‏مِشْرَحٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نِعْمَ أَهْلُ الْبَيْتِ ‏ ‏أَبُو عَبْدِ اللَّهِ ‏ ‏وَأُمُّ عَبْدِ اللَّهِ ‏ ‏وَعَبْدُ اللَّهِ ‏","","",""],[16721,16721,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏قَبَاثُ بْنُ رَزِينٍ اللَّخْمِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَلِيَّ بْنَ رَبَاحٍ اللَّخْمِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ الْجُهَنِيَّ ‏ ‏يَقُولُ ‏ ‏كُنَّا جُلُوسًا فِي الْمَسْجِدِ نَقْرَأُ الْقُرْآنَ فَدَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلَّمَ عَلَيْنَا فَرَدَدْنَا عَلَيْهِ السَّلَامَ ثُمَّ قَالَ ‏ ‏تَعَلَّمُوا كِتَابَ اللَّهِ وَاقْتَنُوهُ ‏ ‏قَالَ وَحَسِبْتُهُ قَالَ وَتَغَنُّوا بِهِ ‏ ‏فَوَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَهُوَ أَشَدُّ ‏ ‏تَفَلُّتًا ‏ ‏مِنْ ‏ ‏الْمَخَاضِ ‏ ‏مِنْ ‏ ‏الْعُقُلِ ‏","","",""],[16722,16722,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏وهَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ مَرْثَدِ بْنِ عَبْدِ اللَّهِ الْيَزَنِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَحَقَّ الشُّرُوطِ أَنْ تُوَفُّوا بِهِ مَا اسْتَحْلَلْتُمْ بِهِ الْفُرُوجَ ‏","","",""],[16723,16723,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏زُهْرَةُ بْنُ مَعْبَدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَمٍّ ‏ ‏لَهُ أَخِي أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ فَأَحْسَنَ ‏ ‏الْوُضُوءَ ‏ ‏ثُمَّ رَفَعَ نَظَرَهُ إِلَى السَّمَاءِ فَقَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ فُتِحَتْ لَهُ ثَمَانِيَةُ أَبْوَابٍ مِنْ الْجَنَّةِ يَدْخُلُ مِنْ أَيِّهَا شَاءَ ‏","","",""],[16724,16724,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏مِشْرَحُ بْنُ هَاعَانَ أَبُو مُصْعَبٍ الْمَعَافِرِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَفُضِّلَتْ سُورَةُ ‏ ‏الْحَجِّ ‏ ‏عَلَى سَائِرِ الْقُرْآنِ بِسَجْدَتَيْنِ قَالَ نَعَمْ فَمَنْ لَمْ يَسْجُدْهُمَا فَلَا يَقْرَأْهُمَا ‏","","",""],[16725,16725,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏مِشْرَحٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ أَنَّ الْقُرْآنَ جُعِلَ فِي ‏ ‏إِهَابٍ ‏ ‏ثُمَّ أُلْقِيَ فِي النَّارِ مَا احْتَرَقَ ‏","","",""],[16726,16726,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏مِشْرَحٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْرَأْ ‏ ‏قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ‏ ‏وَقُلْ أَعُوذُ بِرَبِّ النَّاسِ ‏ ‏فَإِنَّكَ لَا تَقْرَأُ بِمِثْلِهِمَا ‏","","",""],[16727,16727,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏مِشْرَحٌ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْثَرُ مُنَافِقِي أُمَّتِي قُرَّاؤُهَا ‏","","",""],[16728,16728,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيةُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏بَحِيرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجَاهِرُ بِالْقُرْآنِ كَالْجَاهِرِ ‏ ‏بِالصَّدَقَةِ ‏ ‏وَالْمُسِرُّ بِالْقُرْآنِ كَالْمُسِرِّ ‏ ‏بِالصَّدَقَةِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏كَانَ ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏حَافِظًا وَكَانَ يُحَدِّثُنَا وَكَانَ يَحْفَظُ كَتَبْتُ عَنْهُ أَنَا ‏ ‏وَيَحْيَى بْنُ مَعِينٍ ‏","","",""],[16729,16729,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شَهْرُ بْنُ حَوْشَبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَجُلًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ رَجُلٍ يَمُوتُ حِينَ يَمُوتُ وَفِي قَلْبِهِ ‏ ‏مِثْقَالُ ‏ ‏حَبَّةٍ مِنْ ‏ ‏خَرْدَلٍ ‏ ‏مِنْ ‏ ‏كِبْرٍ ‏ ‏تَحِلُّ لَهُ الْجَنَّةُ أَنْ يَرِيحَ رِيحَهَا وَلَا يَرَاهَا فَقَالَ رَجُلٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏يُقَالُ لَهُ ‏ ‏أَبُو رَيْحَانَةَ ‏ ‏وَاللَّهِ يَا رَسُولَ اللَّهِ إِنِّي لَأُحِبُّ الْجَمَالَ ‏ ‏وَأَشْتَهِيهِ حَتَّى إِنِّي لَأُحِبُّهُ فِي ‏ ‏عَلَاقَةِ ‏ ‏سَوْطِي وَفِي ‏ ‏شِرَاكِ ‏ ‏نَعْلِي قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ ذَاكَ الْكِبْرُ إِنَّ اللَّهَ عَزَّ وَجَلَّ جَمِيلٌ يُحِبُّ الْجَمَالَ وَلَكِنَّ الْكِبْرَ مَنْ سَفِهَ الْحَقَّ ‏ ‏وَغَمَصَ ‏ ‏النَّاسَ بِعَيْنَيْهِ ‏","","",""],[16730,16730,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏بَيَانٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ عَامِرٍ الْجُهَنِيُّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَمْ تَرَ آيَاتٍ أُنْزِلْنَ اللَّيْلَةَ لَمْ يُرَ ‏ ‏أَوْ لَا يُرَى ‏ ‏مِثْلَهُنَّ الْمُعَوِّذَتَيْنِ ‏","","",""],[16731,16731,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي عُشَّانَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَيَعْجَبُ مِنْ الشَّابِّ لَيْسَتْ لَهُ ‏ ‏صَبْوَةٌ ‏","","",""],[16732,16732,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي عُشَّانَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوَّلُ خَصْمَيْنِ يَوْمَ الْقِيَامَةِ جَارَانِ ‏","","",""],[16733,16733,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي عُشَّانَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُكْرِهُوا الْبَنَاتِ فَإِنَّهُنَّ الْمُؤْنِسَاتُ الْغَالِيَاتُ ‏","","",""],[16734,16734,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏ضَمْضَمِ بْنِ زُرْعَةَ ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ عُبَيْدٍ الْحَضْرَمِيِّ ‏ ‏عَمَّنْ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَوَّلَ عَظْمٍ مِنْ الْإِنْسَانِ يَتَكَلَّمُ يَوْمَ يُخْتَمُ عَلَى الْأَفْوَاهِ فَخْذُهُ مِنْ الرِّجْلِ الشِّمَالِ ‏","","",""],[16735,16735,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏الرُّعَيْنِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مَالِكٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أُخْتٍ لَهُ نَذَرَتْ أَنْ تَمْشِيَ حَافِيَةً غَيْرَ مُخْتَمِرَةٍ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلْتَخْتَمِرْ وَلْتَرْكَبْ وَلْتَصُمْ ثَلَاثَةَ أَيَّامٍ ‏","","",""],[16736,16736,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جَعْفَرٍ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَرْثَدِ بْنِ عَبْدِ اللَّهِ الْيَزَنِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَحَقَّ الشُّرُوطِ أَنْ يُوَفَّى بِهِ مَا اسْتَحْلَلْتُمْ بِهِ الْفُرُوجَ ‏","","",""],[16737,16737,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ الْجُهَنِيَّ ‏ ‏يَقُولُ ‏ ‏ثَلَاثُ سَاعَاتٍ كَانَ ‏ ‏يَنْهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نُصَلِّيَ فِيهِنَّ أَوْ أَنْ نَقْبُرَ فِيهِنَّ مَوْتَانَا حِينَ تَطْلُعُ الشَّمْسُ ‏ ‏بَازِغَةً ‏ ‏حَتَّى تَرْتَفِعَ وَحِينَ يَقُومُ قَائِمُ الظَّهِيرَةِ حَتَّى تَمِيلَ الشَّمْسُ وَحِينَ ‏ ‏تَضَيَّفُ لِلْغُرُوبِ حَتَّى تَغْرُبَ ‏","","",""],[16738,16738,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُنْزِلَتْ عَلَيَّ آيَاتٌ لَمْ يُرَ مِثْلُهُنَّ ‏ ‏أَوْ لَمْ نَرَ مِثْلَهُنَّ ‏ ‏يَعْنِي الْمُعَوِّذَتَيْنِ ‏","","",""],[16739,16739,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمُ ‏ ‏عَرَفَةَ ‏ ‏وَيَوْمُ النَّحْرِ ‏ ‏وَأَيَّامُ ‏ ‏التَّشْرِيقِ ‏ ‏عِيدُنَا أَهْلَ الْإِسْلَامِ وَهُنَّ أَيَّامُ أَكْلٍ وَشُرْبٍ ‏","","",""],[16740,16740,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُعَاذِ بْنِ عَبْدِ اللَّهِ بْنِ خُبَيْبٍ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْجَذَعِ ‏ ‏فَقَالَ ‏ ‏ضَحِّ بِهِ لَا بَأْسَ بِهِ ‏","","",""],[16741,16741,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَائِذٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَقِيَ اللَّهَ عَزَّ وَجَلَّ لَا يُشْرِكُ بِهِ شَيْئًا لَمْ ‏ ‏يَتَنَدَّ ‏ ‏بِدَمٍ حَرَامٍ دَخَلَ الْجَنَّةَ ‏","","",""],[16742,16742,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُوسَى بْنَ عَلِيِّ بْنِ رَبَاحٍ اللَّخْمِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏ثَلَاثُ سَاعَاتٍ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَانَا أَنْ نُصَلِّيَ فِيهِنَّ وَأَنْ نَقْبُرَ فِيهِنَّ مَوْتَانَا حِينَ تَطْلُعُ الشَّمْسُ ‏ ‏بَازِغَةً ‏ ‏حَتَّى تَرْتَفِعَ وَعِنْدَ قَائِمِ الظَّهِيرَةِ حَتَّى تَمِيلَ الشَّمْسُ وَحِينَ ‏ ‏تَضَيَّفُ لِلْغُرُوبِ حَتَّى تَغْرُبَ ‏","","",""],[16743,16743,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى يَعْنِي ابْنَ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ يَوْمَ النَّحْرِ وَيَوْمَ ‏ ‏عَرَفَةَ ‏ ‏وَأَيَّامَ ‏ ‏التَّشْرِيقِ ‏ ‏هُنَّ عِيدُنَا أَهْلَ الْإِسْلَامِ وَهُنَّ أَيَّامُ أَكَلٍ وَشُرْبٍ ‏","","",""],[16744,16744,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عُهْدَةُ ‏ ‏الرَّقِيقِ ثَلَاثٌ ‏","","",""],[16745,16745,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عُهْدَةُ ‏ ‏الرَّقِيقِ ثَلَاثَةُ أَيَّامٍ ‏","","",""],[16746,16746,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ أَبِي أَيُّوبَ ‏ ‏أَنَّ ‏ ‏يَزِيدَ بْنَ أَبِي حَبِيبٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَا الْخَيْرِ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ أُخْتِي نَذَرَتْ أَنْ تَمْشِيَ إِلَى ‏ ‏بَيْتِ اللَّهِ ‏ ‏عَزَّ وَجَلَّ فَأَمَرَتْنِي أَنْ أَسْتَفْتِيَ لَهَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَفْتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِتَمْشِ وَلْتَرْكَبْ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏أَبُو الْخَيْرِ ‏ ‏لَا يُفَارِقُ ‏ ‏عُقْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏أَنَّ ‏ ‏يَزِيدَ بْنَ أَبِي حَبِيبٍ ‏ ‏أَخْبَرَهُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[16747,16747,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَرْثَدِ بْنِ عَبْدِ اللَّهِ الْيَزَنِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏بَيْنَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ طَلَعَ رَاكِبَانِ ‏ ‏فَلَمَّا رَآهُمَا قَالَ كِنْدِيَّانِ ‏ ‏مَذْحِجِيَّانِ حَتَّى أَتَيَاهُ فَإِذَا رِجَالٌ مِنْ ‏ ‏مَذْحِجٍ ‏ ‏قَالَ فَدَنَا إِلَيْهِ أَحَدُهُمَا لِيُبَايِعَهُ قَالَ فَلَمَّا أَخَذَ بِيَدِهِ قَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَرَأَيْتَ مَنْ رَآكَ فَآمَنَ بِكَ وَصَدَّقَكَ وَاتَّبَعَكَ مَاذَا لَهُ قَالَ ‏ ‏طُوبَى ‏ ‏لَهُ قَالَ فَمَسَحَ عَلَى يَدِهِ فَانْصَرَفَ ثُمَّ أَقْبَلَ الْآخَرُ حَتَّى أَخَذَ بِيَدِهِ لِيُبَايِعَهُ قَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ مَنْ آمَنْ بِكَ وَصَدَّقَكَ وَاتَّبَعَكَ وَلَمْ يَرَكَ قَالَ ‏ ‏طُوبَى ‏ ‏لَهُ ثُمَّ ‏ ‏طُوبَى ‏ ‏لَهُ ثُمَّ ‏ ‏طُوبَى ‏ ‏لَهُ قَالَ فَمَسَحَ عَلَى يَدِهِ فَانْصَرَفَ ‏","","",""],[16748,16748,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏أَنَّ ‏ ‏أَبَا عَبْدِ اللَّهِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏ابْنَ عَابِسٍ الْجُهَنِيَّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ يَا ‏ ‏ابْنَ عَابِسٍ ‏ ‏أَلَا أُخْبِرُكَ بِأَفْضَلِ مَا تَعَوَّذَ بِهِ الْمُتَعَوِّذُونَ قَالَ قُلْتُ بَلَى فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْ أَعُوذُ بِرَبِّ النَّاسِ ‏ ‏وَأَعُوذُ بِرَبِّ الْفَلَقِ ‏ ‏هَاتَيْنِ السُّورَتَيْنِ ‏","","",""],[16749,16749,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ الْعَطَّارُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ هَمَّارٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ ‏ ‏يَا ابْنَ ‏ ‏آدَمَ ‏ ‏اكْفِنِي أَوَّلَ النَّهَارِ بِأَرْبَعِ رَكَعَاتٍ أَكْفِكَ بِهِنَّ آخِرَ يَوْمِكَ ‏","","",""],[16750,16750,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعْدٍ الْأَعْمَى ‏ ‏يُحَدِّثُ ‏ ‏عَطَاءً ‏ ‏قَالَ ‏ ‏رَحَلَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏إِلَى ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏فَأَتَى ‏ ‏مَسْلَمَةَ بْنَ مَخْلَدٍ ‏ ‏فَخَرَجَ إِلَيْهِ قَالَ دُلُّونِي فَأَتَى ‏ ‏عُقْبَةَ ‏ ‏فَقَالَ حَدِّثْنَا مَا سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَبْقَ أَحَدٌ سَمِعَهُ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ سَتَرَ عَلَى مُؤْمِنٍ فِي الدُّنْيَا سَتَرَهُ اللَّهُ يَوْمَ الْقِيَامَةِ فَأَتَى رَاحِلَتَهُ فَرَكِبَ وَرَجَعَ ‏","","",""],[16751,16751,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏مَوْلَى ‏ ‏مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَقُودُ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَاحِلَتَهُ فِي السَّفَرِ فَقَالَ يَا ‏ ‏عُقْبَةُ ‏ ‏أَلَا أُعَلِّمُكَ خَيْرَ سُورَتَيْنِ قُرِئَتَا قُلْتُ بَلَى قَالَ ‏ ‏قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ‏ ‏وَقُلْ أَعُوذُ بِرَبِّ النَّاسِ ‏ ‏فَلَمَّا نَزَلَ صَلَّى بِهِمَا صَلَاةَ ‏ ‏الْغَدَاةِ ‏ ‏قَالَ كَيْفَ ‏ ‏تَرَى يَا ‏ ‏عُقْبَةُ ‏","","",""],[16752,16752,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ الْخَوْلَانِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏وحَدَّثَهُ ‏ ‏أَبُو عُثْمَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏كَانَتْ عَلَيْنَا رِعَايَةُ الْإِبِلِ فَجَاءَتْ ‏ ‏نَوْبَتِي ‏ ‏فَرَوَّحْتُهَا بِعَشِيٍّ فَأَدْرَكْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَائِمًا يُحَدِّثُ النَّاسَ فَأَدْرَكْتُ مِنْ قَوْلِهِ ‏ ‏مَا مِنْ مُسْلِمٍ يَتَوَضَّأُ فَيُحْسِنُ الْوُضُوءَ ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ مُقْبِلًا عَلَيْهِمَا بِقَلْبِهِ وَوَجْهِهِ إِلَّا وَجَبَتْ لَهُ الْجَنَّةُ ‏ ‏فَقُلْتُ ‏ ‏مَا أَجْوَدَ هَذِهِ فَإِذَا قَائِلٌ بَيْنَ يَدَيَّ يَقُولُ الَّتِي قَبْلَهَا أَجْوَدُ مِنْهَا فَنَظَرْتُ فَإِذَا ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏قَالَ إِنِّي قَدْ رَأَيْتُكَ جِئْتَ ‏ ‏آنِفًا ‏ ‏قَالَ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ يَتَوَضَّأُ فَيُسْبِغُ الْوُضُوءَ ثُمَّ يَقُولُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ إِلَّا فُتِحَتْ لَهُ أَبْوَابُ الْجَنَّةِ الثَّمَانِيَةُ يَدْخُلُ مِنْ أَيِّهَا شَاءَ ‏","","",""],[16753,16753,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنَا ‏ ‏قَبَاثُ بْنُ رَزِينٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ نَتَدَارَسُ الْقُرْآنَ قَالَ ‏ ‏تَعَلَّمُوا الْقُرْآنَ وَاقْتَنُوهُ ‏ ‏قَالَ ‏ ‏قَبَاثٌ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا قَالَ وَتَغَنُّوا بِهِ ‏ ‏فَإِنَّهُ أَشَدُّ ‏ ‏تَفَلُّتًا ‏ ‏مِنْ ‏ ‏الْمَخَاضِ ‏ ‏فِي عُقُلِهَا ‏","","",""],[16754,16754,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ نَشِيطٍ الْخَوْلَانِيِّ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏دُخَيْنٍ ‏ ‏كَاتِبِ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعُقْبَةَ ‏ ‏إِنَّ لَنَا جِيرَانًا يَشْرَبُونَ الْخَمْرَ وَأَنَا دَاعٍ لَهُمْ ‏ ‏الشُّرَطَ ‏ ‏فَيَأْخُذُوهُمْ فَقَالَ لَا تَفْعَلْ وَلَكِنْ عِظْهُمْ وَتَهَدَّدْهُمْ قَالَ فَفَعَلَ فَلَمْ يَنْتَهُوا قَالَ فَجَاءَهُ ‏ ‏دُخَيْنٌ ‏ ‏فَقَالَ إِنِّي نَهَيْتُهُمْ فَلَمْ يَنْتَهُوا وَأَنَا دَاعٍ لَهُمْ ‏ ‏الشُّرَطَ ‏ ‏فَقَالَ ‏ ‏عُقْبَةُ ‏ ‏وَيْحَكَ لَا تَفْعَلْ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ سَتَرَ عَوْرَةَ مُؤْمِنٍ فَكَأَنَّمَا اسْتَحْيَا ‏ ‏مَوْءُودَةً ‏ ‏مِنْ قَبْرِهَا ‏","","",""],[16755,16755,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ مَرْثَدِ بْنِ عَبْدِ اللَّهِ الْيَزَنِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِيَّاكُمْ وَالدُّخُولَ عَلَى النِّسَاءِ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يَا رَسُولَ اللَّهِ أَفَرَأَيْتَ الْحَمْوَ قَالَ الْحَمْوُ الْمَوْتُ ‏","","",""],[16756,16756,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ يَوْمًا فَصَلَّى عَلَى أَهْلِ ‏ ‏أُحُدٍ ‏ ‏صَلَاتَهُ عَلَى الْمَيِّتِ ثُمَّ خَرَجَ إِلَى الْمِنْبَرِ فَقَالَ ‏ ‏إِنِّي ‏ ‏فَرَطٌ ‏ ‏لَكُمْ وَأَنَا شَهِيدٌ عَلَيْكُمْ وَإِنِّي وَاللَّهِ ‏ ‏لَأَنْظُرُ إِلَى ‏ ‏حَوْضِي ‏ ‏الْآنَ وَإِنِّي قَدْ أُعْطِيتُ مَفَاتِيحَ خَزَائِنِ الْأَرْضِ وَإِنِّي وَاللَّهِ مَا أَخَافُ عَلَيْكُمْ أَنْ تُشْرِكُوا بَعْدِي وَلَكِنِّي أَخَافُ عَلَيْكُمْ أَنْ تَنَافَسُوا فِيهَا ‏","","",""],[16757,16757,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ سَلَّامٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ الْأَزْرَقِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَيْرَتَانِ إِحْدَاهُمَا يُحِبُّهَا اللَّهُ عَزَّ وَجَلَّ وَالْأُخْرَى يُبْغِضُهَا اللَّهُ ‏ ‏وَمَخِيلَتَانِ ‏ ‏إِحْدَاهُمَا يُحِبُّهَا اللَّهُ عَزَّ وَجَلَّ وَالْأُخْرَى يُبْغِضُهَا اللَّهُ الْغَيْرَةُ فِي ‏ ‏الرَّمْيَةِ ‏ ‏يُحِبُّهَا اللَّهُ عَزَّ وَجَلَّ وَالْغَيْرَةُ فِي غَيْرِهِ يُبْغِضُهَا اللَّهُ ‏ ‏وَالْمَخِيلَةُ ‏ ‏إِذَا تَصَدَّقَ الرَّجُلُ يُحِبُّهَا اللَّهُ ‏ ‏وَالْمَخِيلَةُ ‏ ‏فِي ‏ ‏الْكِبْرِ ‏ ‏يُبْغِضُهَا اللَّهُ ‏","","",""],[16758,16758,"","","‏ ‏وَقَالَ ‏ ‏ثَلَاثٌ مُسْتَجَابٌ لَهُمْ دَعْوَتُهُمْ الْمُسَافِرُ وَالْوَالِدُ وَالْمَظْلُومُ ‏","","",""],[16759,16759,"","","‏ ‏وَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُدْخِلُ بِالسَّهْمِ الْوَاحِدِ الْجَنَّةَ ثَلَاثَةً صَانِعَهُ ‏ ‏وَالْمُمِدَّ ‏ ‏بِهِ وَالرَّامِيَ بِهِ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[16760,16760,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَامِرٍ الْأَسْلَمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عَلِيٍّ الْمِصْرِيِّ ‏ ‏قَالَ ‏ ‏سَافَرْنَا مَعَ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏فَحَضَرَتْنَا الصَّلَاةُ فَأَرَدْنَا أَنْ يَتَقَدَّمَنَا قَالَ قُلْنَا أَنْتَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا تَتَقَدَّمُنَا قَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَمَّ قَوْمًا فَإِنْ أَتَمَّ فَلَهُ التَّمَامُ وَلَهُمْ التَّمَامُ وَإِنْ لَمْ يُتِمَّ فَلَهُمْ التَّمَامُ وَعَلَيْهِ الْإِثْمُ ‏","","",""],[16761,16761,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏حَيْوَةَ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى قَتْلَى ‏ ‏أُحُدٍ ‏ ‏بَعْدَ ثَمَانِ سِنِينَ كَالْمُوَدِّعِ لِلْأَحْيَاءِ وَالْأَمْوَاتِ ثُمَّ طَلَعَ الْمِنْبَرَ فَقَالَ ‏ ‏إِنِّي ‏ ‏فَرَطُكُمْ ‏ ‏وَأَنَا عَلَيْكُمْ شَهِيدٌ وَإِنَّ مَوْعِدَكُمْ الْحَوْضُ وَإِنِّي لَأَنْظُرُ إِلَيْهِ وَلَسْتُ أَخْشَى عَلَيْكُمْ أَنْ تُشْرِكُوا ‏ ‏أَوْ قَالَ تَكْفُرُوا ‏ ‏وَلَكِنْ الدُّنْيَا أَنْ تَنَافَسُوا فِيهَا ‏","","",""],[16762,16762,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ عَبْدُ اللَّهِ بْنُ يَزِيدَ الْمُقْرِئُ ‏ ‏حَدَّثَنَا ‏ ‏حَرْمَلَةُ بْنُ عِمْرَانَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عُشَّانَةَ الْمَعَافِرِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ الْجُهَنِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَتْ ‏ ‏وَقَالَ ‏ ‏مَرَّةً مَنْ كَانَ ‏ ‏لَهُ ثَلَاثُ بَنَاتٍ فَصَبَرَ عَلَيْهِنَّ فَأَطْعَمَهُنَّ وَسَقَاهُنَّ وَكَسَاهُنَّ مِنْ جِدَّتِهِ كُنَّ لَهُ حِجَابًا مِنْ النَّارِ ‏","","",""],[16763,16763,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏أَخْبَرَنَا ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مِشْرَحَ بْنَ هَاعَانَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَعَلَّقَ ‏ ‏تَمِيمَةً ‏ ‏فَلَا أَتَمَّ اللَّهُ لَهُ وَمَنْ تَعَلَّقَ وَدَعَةً فَلَا وَدَعَ اللَّهُ لَهُ ‏","","",""],[16764,16764,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عَمْرٍو ‏ ‏أَنَّ ‏ ‏مِشْرَحَ بْنَ هَاعَانَ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَوْ كَانَ مِنْ بَعْدِي نَبِيٌّ لَكَانَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏","","",""],[16765,16765,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنَا ‏ ‏بَكْرُ بْنُ عَمْرٍو ‏ ‏أَنَّ ‏ ‏مِشْرَحَ بْنَ هَاعَانَ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَهْلُ ‏ ‏الْيَمَنِ ‏ ‏أَرَقُّ قُلُوبًا وَأَلْيَنُ أَفْئِدَةً ‏ ‏وَأَنْجَعُ ‏ ‏طَاعَةً ‏","","",""],[16766,16766,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنِي ‏ ‏بَكْرُ بْنُ عَمْرٍو ‏ ‏أَنَّ ‏ ‏شُعَيْبَ بْنَ زُرْعَةَ ‏ ‏أَخْبَرَهُ قَالَ حَدَّثَنِي ‏ ‏عُقْبَةُ بْنُ عَامِرٍ الْجُهَنِيُّ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ لِأَصْحَابِهِ ‏ ‏لَا تُخِيفُوا أَنْفُسَكُمْ ‏ ‏أَوْ قَالَ الْأَنْفُسَ ‏ ‏فَقِيلَ لَهُ يَا رَسُولَ اللَّهِ وَمَا نُخِيفُ أَنْفُسَنَا قَالَ الدَّيْنَ ‏","","",""],[16767,16767,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عَلِيٍّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ الْجُهَنِيَّ ‏ ‏يَقُولُ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا وَنَحْنُ فِي ‏ ‏الصُّفَّةِ ‏ ‏فَقَالَ أَيُّكُمْ يُحِبُّ أَنْ ‏ ‏يَغْدُوَ ‏ ‏إِلَى ‏ ‏بُطْحَانَ ‏ ‏أَوْ ‏ ‏الْعَقِيقِ ‏ ‏فَيَأْتِيَ كُلَّ يَوْمٍ بِنَاقَتَيْنِ ‏ ‏كَوْمَاوَيْنِ ‏ ‏زَهْرَاوَيْنِ ‏ ‏فَيَأْخُذَهُمَا فِي غَيْرِ إِثْمٍ وَلَا قَطْعِ رَحِمٍ قَالَ قُلْنَا كُلُّنَا يَا رَسُولَ اللَّهِ يُحِبُّ ذَلِكَ قَالَ فَلَأَنْ ‏ ‏يَغْدُوَ ‏ ‏أَحَدُكُمْ إِلَى الْمَسْجِدِ فَيَتَعَلَّمَ آيَتَيْنِ مِنْ كِتَابِ اللَّهِ خَيْرٌ لَهُ مِنْ نَاقَتَيْنِ وَثَلَاثٌ خَيْرٌ مِنْ ثَلَاثٍ وَأَرْبَعٌ خَيْرٌ مِنْ أَرْبَعٍ وَمِنْ أَعْدَادِهِنَّ مِنْ الْإِبِلِ ‏","","",""],[16768,16768,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنِي ‏ ‏مِشْرَحُ بْنُ هَاعَانَ أَبُو الْمُصْعَبِ الْمَعَافِرِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ الْجُهَنِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَوْ أَنَّ الْقُرْآنَ فِي ‏ ‏إِهَابٍ ‏ ‏ثُمَّ أُلْقِيَ فِي النَّارِ مَا احْتَرَقَ ‏","","",""],[16769,16769,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الْمُصْعَبِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَكْثَرُ مُنَافِقِي هَذِهِ الْأُمَّةِ قُرَّاؤُهَا ‏","","",""],[16770,16770,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مِشْرَحُ بْنُ هَاعَانَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقُولُ إِنَّ ‏ ‏أَكْثَرَ مُنَافِقِي هَذِهِ الْأُمَّةِ لَقُرَّاؤُهَا ‏","","",""],[16771,16771,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏مِشْرَحِ بْنِ هَاعَانَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَفُضِّلَتْ سُورَةُ ‏ ‏الْحَجِّ ‏ ‏عَلَى الْقُرْآنِ بِأَنْ جُعِلَ فِيهَا سَجْدَتَانِ فَقَالَ نَعَمْ وَمَنْ لَمْ يَسْجُدْهُمَا فَلَا يَقْرَأْهُمَا ‏","","",""],[16772,16772,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنِي ‏ ‏مِشْرَحُ بْنُ هَاعَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَسْلَمَ النَّاسُ وَآمَنَ ‏ ‏عَمْرُو بْنُ الْعَاصِي ‏","","",""],[16773,16773,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى يَعْنِي ابْنَ أَيُّوبَ الْغَافِقِيَّ ‏ ‏حَدَّثَنِي ‏ ‏عَمِّي ‏ ‏إِيَاسُ بْنُ عَامِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ الْجُهَنِيَّ ‏ ‏يَقُولُ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيمِ ‏} ‏قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اجْعَلُوهَا فِي رُكُوعِكُمْ فَلَمَّا نَزَلَتْ ‏ { ‏سَبِّحْ اسْمَ رَبِّكَ الْأَعْلَى ‏} ‏قَالَ اجْعَلُوهَا فِي سُجُودِكُمْ ‏","","",""],[16774,16774,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي قَبِيلٍ ‏ ‏قَالَ ‏ ‏لَمْ أَسْمَعْ مِنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏إِلَّا هَذَا الْحَدِيثَ ‏ ‏قَالَ ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏وَحَدَّثَنِيهِ ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏هَلَاكُ أُمَّتِي فِي الْكِتَابِ وَاللَّبَنِ قَالُوا يَا رَسُولَ اللَّهِ مَا الْكِتَابُ وَاللَّبَنُ قَالَ يَتَعَلَّمُونَ الْقُرْآنَ فَيَتَأَوَّلُونَهُ عَلَى غَيْرِ مَا أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ وَيُحِبُّونَ اللَّبَنَ فَيَدَعُونَ الْجَمَاعَاتِ وَالْجُمَعَ وَيَبْدُونَ ‏","","",""],[16775,16775,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْخَيْرِ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ ‏ ‏أَبَا تَمِيمٍ الْجَيْشَانِيَّ عَبْدَ اللَّهِ بْنَ مَالِكٍ ‏ ‏يَرْكَعُ رَكْعَتَيْنِ حِينَ يَسْمَعُ أَذَانَ الْمَغْرِبِ قَالَ فَأَتَيْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ الْجُهَنِيَّ ‏ ‏فَقُلْتُ لَهُ أَلَا أُعَجِّبُكَ مِنْ ‏ ‏أَبِي تَمِيمٍ الْجَيْشَانِيِّ ‏ ‏يَرْكَعُ رَكْعَتَيْنِ قَبْلَ صَلَاةِ الْمَغْرِبِ وَأَنَا أُرِيدُ أَنْ ‏ ‏أَغْمِصَهُ ‏ ‏قَالَ ‏ ‏عُقْبَةُ ‏ ‏أَمَا إِنَّا كُنَّا نَفْعَلُهُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ ‏ ‏مَا يَمْنَعُكَ الْآنَ قَالَ الشُّغْلُ ‏","","",""],[16776,16776,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُوبَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ عَبْدِ الْعَزِيزِ الرُّعَيْنِيُّ ‏ ‏وَأَبُو مَرْحُومٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ مُحَمَّدٍ الْقُرَشِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّهُ ‏ ‏قَالَ ‏ ‏أَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أَقْرَأَ ‏ ‏بِالْمُعَوِّذَاتِ ‏ ‏فِي ‏ ‏دُبُرِ ‏ ‏كُلِّ صَلَاةٍ ‏","","",""],[16777,16777,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏ثَنَا ‏ ‏حَيْوَةُ ‏ ‏وَابْنُ لَهِيعَةَ ‏ ‏قَالَا سَمِعْنَا ‏ ‏يَزِيدَ بْنَ أَبِي حَبِيبٍ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏أَبُو عِمْرَانَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏تَعَلَّقْتُ بِقَدَمِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ أَقْرِئْنِي سُورَةَ ‏ ‏هُودٍ ‏ ‏وَسُورَةَ ‏ ‏يُوسُفَ ‏ ‏فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عُقْبَةُ بْنَ عَامِرٍ ‏ ‏إِنَّكَ لَمْ تَقْرَأْ سُورَةً أَحَبَّ إِلَى اللَّهِ عَزَّ وَجَلَّ وَلَا أَبْلَغَ عِنْدَهُ مِنْ ‏ ‏قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏لَمْ يَكُنْ ‏ ‏أَبُو عِمْرَانَ ‏ ‏يَدَعُهَا وَكَانَ لَا يَزَالُ يَقْرَؤُهَا فِي صَلَاةِ الْمَغْرِبِ ‏","","",""],[16778,16778,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا خَيْرَ فِيمَنْ لَا يُضِيفُ ‏","","",""],[16779,16779,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏مِشْرَحِ بْنِ هَاعَانَ الْمَعَافِرِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَوْ كَانَ الْقُرْآنُ فِي ‏ ‏إِهَابٍ ‏ ‏مَا مَسَّتْهُ النَّارُ ‏","","",""],[16780,16780,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو السَّمْحِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو قَبِيلٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنِّي أَخَافُ عَلَى أُمَّتِي اثْنَتَيْنِ الْقُرْآنَ ‏ ‏وَاللَّبَنَ ‏ ‏أَمَّا ‏ ‏اللَّبَنُ ‏ ‏فَيَبْتَغُونَ ‏ ‏الرِّيفَ وَيَتَّبِعُونَ الشَّهَوَاتِ وَيَتْرُكُونَ الصَّلَوَاتِ وَأَمَّا الْقُرْآنُ فَيَتَعَلَّمُهُ الْمُنَافِقُونَ فَيُجَادِلُونَ بِهِ الْمُؤْمِنِينَ ‏","","",""],[16781,16781,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي مَنْصُورٍ ‏ ‏عَنْ ‏ ‏دُخَيْنٍ الْحَجْرِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقْبَلَ إِلَيْهِ ‏ ‏رَهْطٌ ‏ ‏فَبَايَعَ تِسْعَةً وَأَمْسَكَ عَنْ وَاحِدٍ فَقَالُوا يَا رَسُولَ اللَّهِ بَايَعْتَ تِسْعَةً وَتَرَكْتَ هَذَا قَالَ إِنَّ عَلَيْهِ ‏ ‏تَمِيمَةً ‏ ‏فَأَدْخَلَ يَدَهُ فَقَطَعَهَا فَبَايَعَهُ وَقَالَ ‏ ‏مَنْ عَلَّقَ ‏ ‏تَمِيمَةً ‏ ‏فَقَدْ أَشْرَكَ ‏","","",""],[16782,16782,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏كَعْبُ بْنُ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ شِمَاسَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا ‏ ‏النَّذْرُ كَفَّارَتُهُ كَفَّارَةُ الْيَمِينِ ‏","","",""],[16783,16783,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏بَعْجَةَ الْجُهَنِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحَايَا بَيْنَ أَصْحَابِهِ فَصَارَ ‏ ‏لِعُقْبَةَ ‏ ‏جَذَعَةٌ ‏ ‏قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنِّي صَارَتْ لِي ‏ ‏جَذَعَةٌ ‏ ‏قَالَ ضَحِّ بِهَا ‏","","",""],[16784,16784,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنِي ‏ ‏الْأَسْلَمِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَلِيٍّ الْهَمْدَانِيُّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏فِي مَخْرَجٍ خَرَجْنَاهُ فَحَانَتْ صَلَاةٌ فَسَأَلْنَاهُ أَنْ يَؤُمَّنَا فَأَبَى عَلَيْنَا وَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَؤُمُّ عَبْدٌ قَوْمًا إِلَّا تَوَلَّى مَا كَانَ عَلَيْهِمْ فِي صَلَاتِهِمْ إِنْ أَحْسَنَ فَلَهُ وَإِنْ أَسَاءَ فَعَلَيْهِ ‏","","",""],[16785,16785,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَارِثُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْكَيِّ وَكَانَ يَكْرَهُ شُرْبَ ‏ ‏الْحَمِيمِ ‏ ‏وَكَانَ إِذَا اكْتَحَلَ اكْتَحَلَ ‏ ‏وِتْرًا ‏ ‏وَإِذَا ‏ ‏اسْتَجْمَرَ ‏ ‏اسْتَجْمَرَ ‏ ‏وِتْرًا ‏","","",""],[16786,16786,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ هُبَيْرَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ جُبَيْرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏اسْتَجْمَرَ ‏ ‏أَحَدُكُمْ ‏ ‏فَلْيَسْتَجْمِرْ ‏ ‏وِتْرًا ‏ ‏وَإِذَا اكْتَحَلَ فَلْيَكْتَحِلْ ‏ ‏وِتْرًا ‏","","",""],[16787,16787,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اكْتَحَلَ أَحَدُكُمْ فَلْيَكْتَحِلْ ‏ ‏وِتْرًا ‏ ‏وَإِذَا ‏ ‏اسْتَجْمَرَ ‏ ‏فَلْيَسْتَجْمِرْ ‏ ‏وِتْرًا ‏","","",""],[16788,16788,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏هَارُونَ ‏ ‏مِثْلَهُ سَوَاءً ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏مَوْلًى لِشُرَحْبِيلَ ابْنِ حَسَنَةَ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏وَحُذَيْفَةَ بْنَ الْيَمَانِ ‏ ‏يَقُولَانِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلْ مَا ‏ ‏رَدَّتْ ‏ ‏عَلَيْكَ قَوْسُكَ ‏","","",""],[16789,16789,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏مَوْلَى شُرَحْبِيلَ ابْنِ حَسَنَةَ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏وَحُذَيْفَةَ بْنَ الْيَمَانِ ‏ ‏يَقُولَانِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلْ مَا ‏ ‏رَدَّتْ ‏ ‏عَلَيْكَ قَوْسُكَ ‏","","",""],[16790,16790,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَأَظُنُّ أَنِّي سَمِعْتُهُ ‏ ‏مِنْهُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏أَنَّ ‏ ‏هِشَامَ بْنَ أَبِي رُقَيَّةَ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏سَمِعْتُ ‏ ‏مَسْلَمَةَ بْنَ مَخْلَدٍ ‏ ‏وَهُوَ قَاعِدٌ عَلَى الْمِنْبَرِ يَخْطُبُ النَّاسَ وَهُوَ يَقُولُ يَا أَيُّهَا النَّاسُ أَمَا لَكُمْ فِي ‏ ‏الْعَصَبِ ‏ ‏وَالْكَتَّانِ مَا ‏ ‏يَكْفِيكُمْ عَنْ الْحَرِيرِ وَهَذَا رَجُلٌ فِيكُمْ يُخْبِرُكُمْ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُمْ يَا ‏ ‏عُقْبَةُ ‏ ‏فَقَامَ ‏ ‏عُقْبَةُ بْنُ عَامِرٍ ‏ ‏وَأَنَا أَسْمَعُ فَقَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَذِبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ وَأَشْهَدُ أَنِّي سَمِعْتُهُ يَقُولُ مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا حُرِمَهُ أَنْ يَلْبَسَهُ فِي الْآخِرَةِ ‏","","",""],[16791,16791,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا حَدَّثَنَاهُ ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ ‏ ‏سُرَيْجٌ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏قَالَ ‏ ‏هَارُونُ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي عَلِيٍّ ثُمَامَةَ بْنِ شُفَيٍّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَهُوَ عَلَى الْمِنْبَرِ ‏ { ‏وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ ‏} ‏أَلَا إِنَّ الْقُوَّةَ الرَّمْيُ أَلَا إِنَّ الْقُوَّةَ الرَّمْيُ أَلَا إِنَّ الْقُوَّةَ الرَّمْيُ ‏","","",""],[16792,16792,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏وَسُرَيْجُ بْنُ مَعْرُوفٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي عَلِيٍّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَتُفْتَحُ عَلَيْكُمْ أَرَضُونَ ‏ ‏وَيَكْفِيكُمُ اللَّهُ عَزَّ وَجَلَّ فَلَا يُعْجِزُ أَحَدُكُمْ أَنْ يَلْهُوَ بِأَسْهُمِهِ ‏ ‏قَالَ ‏ ‏سُرَيْجٌ ‏ ‏ثُمَامَةَ بْنِ شُفَيٍّ ‏","","",""],[16793,16793,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ شِمَاسَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَيِّتُ مِنْ ذَاتِ ‏ ‏الْجَنْبِ ‏ ‏شَهِيدٌ ‏","","",""],[16794,16794,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏مِشْرَحُ بْنُ هَاعَانَ ‏ ‏أَنَّهُ قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ مَاتَ ‏ ‏مُرَابِطًا ‏ ‏فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ أُجْرِيَ عَلَيْهِ أَجْرُهُ ‏","","",""],[16795,16795,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏وَيَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏مِشْرَحُ بْنُ هَاعَانَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏كُلُّ مَيِّتٍ يُخْتَمُ عَلَى عَمَلِهِ إِلَّا ‏ ‏الْمُرَابِطَ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏فِي سَبِيلِ اللَّهِ ‏ ‏فَإِنَّهُ ‏ ‏يُجْرَى عَلَيْهِ أَجْرُ عَمَلِهِ حَتَّى يَبْعَثَهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[16796,16796,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏وَمُوسَى بْنُ دَاوُدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏أَنَّ غُلَامًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏مُوسَى ‏ ‏فِي حَدِيثِهِ سَأَلَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ أُمِّي مَاتَتْ وَتَرَكَتْ حُلِيًّا أَفَأَتَصَدَّقُ بِهِ عَنْهَا قَالَ أُمُّكَ أَمَرَتْكَ بِذَلِكَ قَالَ لَا قَالَ فَأَمْسِكْ عَلَيْكَ حُلِيَّ أُمِّكَ ‏ ‏حَدَّثَنَاه ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ يَعْنِي الْمُقْرِئَ ‏","","",""],[16797,16797,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏وَالْحَسَنُ بْنُ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَتَصَدَّقَ بِحُلِيٍّ كَانَ لِأُمِّهِ عَنْ أُمِّهِ بَعْدَ مَوْتِهَا فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَتْكَ بِذَلِكَ قَالَ لَا قَالَ فَلَا ‏","","",""],[16798,16798,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُشَّانَةَ حَيُّ بْنُ يُؤْمِنَ الْمَعَافِرِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَدْنُو الشَّمْسُ مِنْ الْأَرْضِ فَيَعْرَقُ النَّاسُ فَمِنْ النَّاسِ مَنْ يَبْلُغُ عَرَقُهُ ‏ ‏عَقِبَيْهِ ‏ ‏وَمِنْهُمْ مَنْ يَبْلُغُ إِلَى نِصْفِ السَّاقِ وَمِنْهُمْ مَنْ يَبْلُغُ إِلَى رُكْبَتَيْهِ وَمِنْهُمْ مَنْ يَبْلُغُ ‏ ‏الْعَجُزَ ‏ ‏وَمِنْهُمْ مَنْ يَبْلُغُ الْخَاصِرَةَ وَمِنْهُمْ مَنْ يَبْلُغُ ‏ ‏مَنْكِبَيْهِ ‏ ‏وَمِنْهُمْ مَنْ يَبْلُغُ عُنُقَهُ وَمِنْهُمْ مَنْ يَبْلُغُ وَسَطَ ‏ ‏فِيهِ وَأَشَارَ بِيَدِهِ ‏ ‏فَأَلْجَمَهَا ‏ ‏فَاهُ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُشِيرُ هَكَذَا وَمِنْهُمْ مَنْ ‏ ‏يُغَطِّيهِ عَرَقُهُ وَضَرَبَ بِيَدِهِ إِشَارَةً ‏","","",""],[16799,16799,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُشَّانَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا تَطَهَّرَ الرَّجُلُ ثُمَّ أَتَى الْمَسْجِدَ ‏ ‏يَرْعَى الصَّلَاةَ كَتَبَ لَهُ كَاتِبَاهُ ‏ ‏أَوْ كَاتِبُهُ ‏ ‏بِكُلِّ خُطْوَةٍ ‏ ‏يَخْطُوهَا إِلَى الْمَسْجِدِ عَشْرَ حَسَنَاتٍ وَالْقَاعِدُ ‏ ‏يَرْعَى الصَّلَاةَ ‏ ‏كَالْقَانِتِ ‏ ‏وَيُكْتَبُ مِنْ الْمُصَلِّينَ مِنْ حِينِ يَخْرُجُ مِنْ بَيْتِهِ حَتَّى يَرْجِعَ إِلَيْهِ ‏","","",""],[16800,16800,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَمْرٍو الْمَعَافِرِيُّ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَاعِيًا فَاسْتَأْذَنْتُهُ أَنْ آكُلَ مِنْ ‏ ‏الصَّدَقَةِ ‏ ‏فَأَذِنَ لِي ‏","","",""]];
